Object.assign(window.TEM8_DICTIONARY, {"legged":{"oxford":{"phon":"leɡ","pos":"noun","senses":[{"en":"one of the long parts that connect the feet to the rest of the body","cn":"腿"},{"en":"the leg of an animal, especially the top part, cooked and eaten （","cn":"尤指供食用的）动物的腿，腿肉"}]}},"legend":{"media":{"uk":"media/uk/legend__gb_1.mp3","us":"media/us/legend__us_1.mp3"},"oxford":{"phon":"ˈledʒənd","pos":"noun","senses":[{"en":"a story from ancient times about people and events, that may or may not be true; this type of story","cn":"传说；传奇故事","g":"[countable, uncountable]","ex":{"en":"The film is based on the legend of Robin Hood.","cn":"这部电影是根据罗宾汉的传奇故事改编的。"}},{"en":"a very famous person, especially in a particular field, who is admired by other people","cn":"（尤指某领域中的）传奇人物","g":"[countable]","ex":{"en":"a jazz/screen/sporting legend","cn":"爵士乐／银幕／体育传奇人物"}},{"en":"the explanation of a map or a diagram in a book","cn":"（地图或书中图表的）图例，说明，解释","g":"[countable]","lab":"specialist"},{"en":"a piece of writing on a sign, a label, a coin, etc.","cn":"（标志、徽记、硬币等物品上的）刻印文字，铭文","g":"[countable]","lab":"formal"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"传说；传奇","en":"A legend is a very old and popular story that may be true.","ex":{"en":"...the legends of ancient Greece","cn":"古希腊传说"}},{"pos":"N-COUNT 可数名词","cn":"传奇人物；巨匠；大师","en":"If you refer to someone as a legend, you mean that they are very famous and admired by a lot of people.","ex":{"en":"...blues legends John Lee Hooker and B.B. King.","cn":"布鲁斯音乐大师约翰·李·胡克和B. B. 金"}},{"pos":"N-VAR 可变名词","cn":"传奇故事；家喻户晓的故事；热门故事","en":"A legend is a story that people talk about, concerning people, places, or events that exist or are famous at the present time.","ex":{"en":"The incident has since become a family legend","cn":"此事自此成为了家族传奇。"}}]},"examples":[{"en":"Legend has it that the lake was formed by the tears of a god.","cn":"据传说这个湖是一位神仙的眼泪积聚而成的。"},{"en":"Many of golf's living legends were playing.","cn":"当时有许多当世高尔夫球传奇选手在打球。"}]},"leach":{"media":{"uk":"media/uk/leach__gb_1.mp3","us":"media/us/leach__us_1.mp3"},"oxford":{"phon":"liːtʃ","pos":"verb","senses":[{"en":"to be removed from soil, etc. by water passing through it","cn":"淋洗；淋失","g":"[intransitive]","ex":{"en":"Nitrates leach from the soil into rivers.","cn":"硝酸盐由土壤淋洗入江河。"}},{"en":"to remove chemicals, minerals, etc. from soil","cn":"过滤；滤去","g":"[transitive]","ex":{"en":"The nutrient is quickly leached away.","cn":"养分很快就被滤掉了。"}}]},"examples":[{"en":"Nitrates leach from the soil into rivers.","cn":"硝酸盐由土壤渗入江河。"},{"en":"The nutrient is quickly leached away.","cn":"养分很快就被滤掉了。"}]},"leadership":{"media":{"uk":"media/uk/leadership__gb_1.mp3","us":"media/us/leadership__us_1.mp3"},"oxford":{"phon":"ˈliːdəʃɪp","pos":"noun","senses":[{"en":"the state or position of being a leader","cn":"领导；领导地位","g":"[uncountable]","ex":{"en":"a leadership role/position","cn":"领导角色／岗位"}},{"en":"the ability to be a leader or the qualities a good leader should have","cn":"领导才能；领导应有的品质","g":"[uncountable]","ex":{"en":"Strong leadership is needed to captain the team.","cn":"担任这个队的队长需要强有力的领导才能。"}},{"en":"a group of leaders of a particular organization, etc.","cn":"领导班子；领导层","g":"[countable + singular or plural verb]","ex":{"en":"The party leadership is/are divided.","cn":"这个党的领导层意见不合。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"领导层；领导班子","en":"You refer to people who are in control of a group or organization as the leadership .","ex":{"en":"He is expected to hold talks with both the Croatian and Slovenian leaderships.","cn":"预计他将与克罗地亚和斯洛文尼亚领导层举行会谈。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"领导；领导权；领导地位","en":"Someone's leadership is their position or state of being in control of a group of people.","ex":{"en":"He praised her leadership during the crisis","cn":"他赞扬她在危机中领导有方。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"领导才能；领导方法；领导作风","en":"Leadership refers to the qualities that make someone a good leader, or the methods a leader uses to do his or her job.","ex":{"en":"What most people want to see is determined, decisive action and firm leadership.","cn":"大多数人希望看到的是果决的行动和强有力的领导作风。"}}]},"examples":[{"en":"Strong leadership is needed to captain the team.","cn":"担任这个队的队长需要强有力的领导才能。"},{"en":"The party thrived under his leadership.","cn":"该党在他的领导下壮大起来。"}]},"let":{"media":{"uk":"media/uk/let__gb_1.mp3","us":"media/us/let__us_1.mp3"},"oxford":{"phon":"let","pos":"verb","senses":[{"en":"used for making suggestions or as a polite way of telling people what you want them to do","cn":"（用于提出建议或礼貌地要求别人做什么时说）让我们","g":"[no passive]","lab":"formal","sc":"making suggestions","ex":{"en":"‘Shall we check it again?’ ‘Yes, let's.’","cn":"“我们再检查一下好吗？”“好的。”"}},{"en":"used for offering help to somebody","cn":"（提出帮助时说）让，由","g":"[no passive]","sc":"offering help","ex":{"en":"Let me help you with that.","cn":"这事我来帮你吧。"}},{"en":"used for making requests or giving instructions","cn":"（提出请求或给予指示时说）要","g":"[no passive]","sc":"making requests","ex":{"en":"Let me have your report by Friday.","cn":"星期五以前要把你的报告交给我。"}},{"en":"to allow somebody to do something or something to happen without trying to stop it","cn":"允许；让","g":"[no passive]","sc":"allow","ex":{"en":"Let them splash around in the pool for a while.","cn":"让他们在水池里扑腾一会儿吧。"}},{"en":"to give somebody permission to do something","cn":"准许；许可；同意","sc":"allow","ex":{"en":"They won't let him leave the country.","cn":"他们不许他离开这个国家。"}},{"en":"to allow somebody/something to go somewhere","cn":"允许（去某处）","sc":"allow","ex":{"en":"to let somebody into the house","cn":"允许某人进屋"}},{"en":"used to show that you are not afraid or worried about somebody doing something","cn":"（表示不害怕或担忧某人做某事）让","g":"[no passive]","sc":"challenging","ex":{"en":"If he thinks he can cheat me, just let him try!","cn":"要是他以为能够骗过我，就让他来试一下吧！"}},{"en":"used to express a strong wish for something to happen","cn":"（表达强烈的愿望）让","g":"[no passive]","lab":"literary","sc":"wishing","ex":{"en":"Let her come home safely!","cn":"让她平平安安回家吧！"}},{"en":"used to introduce what you are going to say or do","cn":"（引出要讲或要做的事）让","g":"[no passive]","sc":"introducing something","ex":{"en":"Let me give you an example.","cn":"让我来举一个例子吧。"}},{"en":"used to say that you are supposing something to be true when you calculate something","cn":"（计算时说）假设，设","g":"[no passive]","lab":"specialist","sc":"in calculating","ex":{"en":"Let line AB be equal to line CD.","cn":"设线 AB 与线 CD 等长。"}},{"en":"to allow somebody to use a house, room, etc. in return for regular payments","cn":"出租（房屋、房间等）","lab":"especially British English","sc":"house/room","ex":{"en":"I let the spare room.","cn":"我把那间空房出租了。"}},{"en":"small; not very important","cn":"小的；不很重要的","ex":{"en":"booklet","cn":"小册子"},"pos":"suffix"},{"en":"a serve that lands in the correct part of the court but must be taken again because it has touched the top of the net","cn":"（发球时的）擦网球","sc":"in tennis","pos":"noun"},{"en":"an act of renting a house, flat, room, etc.; a house, flat, room etc. that is available to rent","cn":"房屋出租；出租房","lab":"British English","sc":"house/room","ex":{"en":"a long-term/short-term let","cn":"长期／短期出租"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"允许，任由，让（某事发生）","en":"If you let something happen, you allow it to happen without doing anything to stop or prevent it.","ex":{"en":"People said we were interfering with nature, and that we should just let the animals die","cn":"人们说我们是在干涉自然界，还说我们应该任由动物死去。"}},{"pos":"VERB 动词","cn":"允许，准许，同意（某人做某事）","en":"If you let someone do something, you give them your permission to do it.","ex":{"en":"I love sweets but Mum doesn't let me have them very often","cn":"我爱吃糖，可妈妈不让我常吃。"}},{"pos":"VERB 动词","cn":"（开门、让路等）允许（…进、出或通过）","en":"If you let someone into, out of, or through a place, you allow them to enter, leave, or go through it, for example by opening a door or making room for them.","ex":{"en":"I had to get up at seven o'clock this morning to let them into the building because they had lost their keys","cn":"今天早上我不得不7点钟就起床开门让他们进楼，因为他们把钥匙弄丢了。"}},{"pos":"VERB 动词","cn":"（用于引出要说的话）让我，我来","en":"You use let me when you are introducing something you want to say.","ex":{"en":"Let me say it again. I despised Wade's life","cn":"我再说一遍。我厌恶韦德的生活方式。"}},{"pos":"VERB 动词","cn":"（用于礼貌地表示愿意提供帮助）让我，我来","en":"You use let me when you are offering politely to do something.","ex":{"en":"Let me take your coat","cn":"我来帮您拿外套。"}},{"pos":"VERB 动词","cn":"（用于将他人的注意力引向下面的话题）让我们","en":"You say let's or, in more formal English, let us, to direct the attention of the people you are talking to towards the subject that you want to consider next.","ex":{"en":"Let's consider ways of making it easier","cn":"咱们来想想办法把它变得更容易些吧。"}},{"pos":"VERB 动词","cn":"（用于提出建议或表示赞同）让我们","en":"You say let's or, in formal English, let us, when you are making a suggestion that involves both you and the person you are talking to, or when you are agreeing to a suggestion of this kind.","ex":{"en":"I'm bored. Let's go home","cn":"我觉得好无聊。我们回家吧。"}},{"pos":"VERB 动词","cn":"（用于委婉地发出指令）让我们","en":"Someone in authority, such as a teacher, can use let's or, in more formal English, let us, in order to give a polite instruction to another person or group of people.","ex":{"en":"Let's have some hush, please","cn":"请大家安静一下。"}},{"pos":"VERB 动词","cn":"（表示犹豫或思考）让我看看/让我想想","en":"People often use let in expressions such as let me see or let me think when they are hesitating or thinking of what to say next.","ex":{"en":"Now, let's see. Where did I leave my bag?","cn":"嗯，我想想。我把包放哪儿了？"}},{"pos":"VERB 动词","cn":"（表示不关心）任由，让，随","en":"You can use let to say that you do not care if someone does something, although you think it is unpleasant or wrong.","ex":{"en":"If he wants to do that, let him do it","cn":"他要做，就让他做好了。"}},{"pos":"VERB 动词","cn":"（表示认为某人应该做某事）让","en":"You can use let when you are saying what you think someone should do, usually when they are behaving in a way that you think is unreasonable or wrong.","ex":{"en":"Let him get his own cup of tea","cn":"自己的茶让他自己端。"}},{"pos":"VERB 动词","cn":"（表示祈祷或盼望）让","en":"You can use let when you are praying or hoping very much that something will happen.","ex":{"en":"Please God, let him telephone me.","cn":"上帝啊，求你让他打电话给我吧。"}},{"pos":"VERB 动词","cn":"假设；假定；如果","en":"You can use let to introduce an assumption on which you are going to base a theory, calculation, or story.","ex":{"en":"Let x equal 5 and y equal 3","cn":"设x等于5，y等于3。"}},{"pos":"VERB 动词","cn":"出租（房屋、土地等）","en":"If you let your house or land to someone, you allow them to use it in exchange for money that they pay you regularly.","ex":{"en":"She is thinking of letting her house to an American serviceman","cn":"她正考虑把房子租给一个美国军人。"}},{"pos":"N-COUNT 可数名词","cn":"（网球或羽毛球发球时的）擦网球，触网重发","en":"In tennis or badminton, if you serve a let, the ball or shuttlecock touches the net but lands in the correct part of the court. You then serve again."},{"pos":"PHR-CONJ-COORD","cn":"（通常用在否定句后）遑论，更别提，更不用说","en":"Let alone is used after a statement, usually a negative one, to indicate that the statement is even more true of the person, thing, or situation that you are going to mention next.","ex":{"en":"It is incredible that the 12-year-old managed to even reach the pedals, let alone drive the car.","cn":"12岁的孩子能踩到踏板已经是不可思议，就更不用说开车了。"}},{"pos":"PHRASE 短语","cn":"不打扰；不干涉","en":"To let someone be means to leave them alone and not interfere in what they are doing.","ex":{"en":"If your child is really sick and needs sleep and quiet, let him be.","cn":"如果孩子真的病了，需要睡眠和静养的话，就不要去打扰他。"}},{"pos":"PHRASE 短语","cn":"松开；放开","en":"If you let go of someone or something, you stop holding them.","ex":{"en":"She let go of Mona's hand and took a sip of her drink","cn":"她放开莫娜的手，抿了一口饮料。"}},{"pos":"PHRASE 短语","cn":"放弃，舍弃（感情、态度、控制权）","en":"If you let go of a feeling, attitude, or the control that you have over something, you accept that you should give it up or that it should no longer influence you.","ex":{"en":"In therapy, she began to let go of her obsession with Mike","cn":"在心理治疗中，她开始逐渐放下对麦克的痴迷。"}},{"pos":"PHRASE 短语","cn":"放走；释放；让…逃走","en":"If you let someone or something go, you allow them to leave or escape.","ex":{"en":"They held him for three hours and they let him go","cn":"他们扣留了他3个小时后放走了他。"}},{"pos":"PHRASE 短语","cn":"解雇；解聘；让…离职","en":"When someone leaves a job, either because they are told to or because they want to, the employer sometimes says that they are letting that person go .","ex":{"en":"I've assured him I have no plans to let him go","cn":"我向他保证，我绝对没打算让他走人。"}},{"pos":"PHRASE 短语","cn":"不予理会；不予追究","en":"If someone says or does something that you think is annoying or stupid and you let it go, you do not react to it or say anything about it.","ex":{"en":"Let it go, he thought. He didn't feel like arguing.","cn":"管它呢，他想。他并不想争吵。"}},{"pos":"PHRASE 短语","cn":"放松；随心所欲","en":"If you let yourself go, you relax and behave much more freely than usual.","ex":{"en":"Stop worrying about what you're feeling. Let yourself go.","cn":"不要总想着自己是什么感觉。放轻松点。"}},{"pos":"PHRASE 短语","cn":"不修边幅；不注意仪表","en":"If someone lets themselves go, they pay less attention to themselves or their appearance than they used to, so that they look untidy or unattractive.","ex":{"en":"If you have let yourself go, you should consider doing something about it for the sake of your health.","cn":"你以前要是对自己不管不顾，现在应该为了自己的健康着想而改变一下。"}},{"pos":"PHRASE 短语","cn":"(使自己)陷入，卷入，招惹（麻烦等）","en":"If you say that you did not know what you were letting yourself in for when you decided to do something, you mean you did not realize how difficult, unpleasant, or expensive it was going to be.","ex":{"en":"He got the impression that Miss Hawes had no idea of what she was letting herself in for","cn":"他觉得霍斯小姐根本不知道自己会惹来什么麻烦。"}},{"pos":"PHRASE 短语","cn":"告知；告诉；使知情","en":"If you let someone know something, you tell them about it or make sure that they know about it.","ex":{"en":"They want to let them know that they are safe","cn":"他们想让他们知道他们安全无事。"}},{"pos":"PHRASE 短语","cn":"泄露；无意中吐露","en":"If you let drop ,let fall, or let slip information, you reveal it casually or by accident, during a conversation about something else.","ex":{"en":"How could she know about that? He'd certainly never let drop any hint","cn":"她是怎么知道的？他绝对没有走漏半点风声。"}},{"pos":"PHRASE 短语","cn":"放任；给予完全的自由","en":"If you say that someone has been let loose in a place or situation, you mean that they have been given complete freedom to do what they like in that place or situation, and you suggest that this may be risky.","ex":{"en":"She has all the glee of a little girl let loose in a sweetie shop","cn":"她像糖果店里无人管束的小女孩那样兴高采烈。"}},{"pos":"PHRASE 短语","cn":"（常指地）发（声），讲（话）","en":"If someone lets loose a sound or remark, they make it, often suddenly.","ex":{"en":"He let loose a long, deep sigh","cn":"他突然喟然长叹了一声。"}},{"pos":"","cn":"","en":"to let fly→see: ; to let your hair down→see: ; to let someone off the hook→see: ; to let it be known→see: ; to live and let live→see: ; to let the side down→see: ; to let off steam→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"使美中不足；使差强人意；使不理想","en":"If something lets you down, it is the reason you are not as successful as you could have been.","ex":{"en":"Many believe it was his shyness and insecurity which let him down","cn":"很多人认为是他的腼腆和缺乏安全感拖了他的后腿。"}},{"pos":"PHRASAL VERB 短语动词","cn":"给（轮胎等）放气","en":"If you let down something such as a tyre, you allow air to escape from it.","ex":{"en":"I let the tyres down on his car","cn":"我把他的汽车轮胎放了气。"}},{"pos":"","cn":"","en":"相关词组：let down let down let in let in on let into let off let on let out let up let up on"}]},"examples":[{"en":"I volunteered to help, and then I thought ‘Oh no, what have I let myself in for!’","cn":"我自告奋勇要帮忙，然后又一想：“啊，不好，我干吗把自己卷进去呢！”"},{"en":"I can let you have it for, well let's say £100.","cn":"我可以把这东西卖给你，嗯，比如说给我 100 英镑吧。"}]},"legal":{"media":{"uk":"media/uk/legal__gb_1.mp3","us":"media/us/legal__us_1.mp3"},"oxford":{"phon":"ˈliːɡl","pos":"adjective","senses":[{"en":"connected with the law","cn":"与法律有关的；法律的","g":"[only before noun]","ex":{"en":"the legal profession/system","cn":"法律行业／体系"}},{"en":"allowed or required by law","cn":"法律允许的；合法的；法律要求的","ex":{"en":"legal rights/obligations","cn":"法律权利／义务"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"法律（上）的；司法的；法制的","en":"Legal is used to describe things that relate to the law.","ex":{"en":"He vowed to take legal action.","cn":"他誓言要采取法律行动。"}},{"pos":"ADJ 形容词","cn":"合法的；法定的","en":"An action or situation that is legal is allowed or required by law.","ex":{"en":"What I did was perfectly legal.","cn":"我所做的绝对合法。"}}]},"examples":[{"en":"The driver was more than three times over the legal limit (= the amount of alcohol you are allowed to have in your body when you are driving).","cn":"那名司机体内的酒精含量超过了法律允许限度的三倍。"},{"en":"to be legally responsible for sb/sth","cn":"对某人/某事负有法律责任"}]},"lends":{"oxford":{"phon":"lend","pos":"verb","senses":[{"en":"to give sth to sb or allow them to use sth that belongs to you, which they have to return to you later","cn":"借给；借出"},{"en":"to give money to sb on condition that they pay it back over a period of time and pay interest on it","cn":"贷（款）"}]}},"leather":{"media":{"img":["media/pic/coats_jackets_comp.jpg","media/thumb/leatherjacket.jpg"],"uk":"media/uk/leather__gb_1.mp3","us":"media/us/leather__us_1.mp3"},"oxford":{"phon":"ˈleðə(r)","pos":"noun","senses":[{"en":"material made by removing the hair or fur from animal skins and preserving the skins using special processes","cn":"皮革","g":"[uncountable]","ex":{"en":"a leather jacket","cn":"皮夹克"}},{"en":"clothes made from leather, especially those worn by people riding motorcycles","cn":"（尤指骑摩托车人穿的）皮衣，皮外套","g":"[plural]","ex":{"en":"a biker in black leathers","cn":"穿黑皮衣的摩托车手"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"皮革","en":"Leather is treated animal skin which is used for making shoes, clothes, bags, and furniture.","ex":{"en":"He wore a leather jacket and dark trousers.","cn":"他身穿皮夹克和深色裤子。"}},{"pos":"N-PLURAL 复数名词","cn":"（尤指骑摩托车者穿的）皮外套，皮衣","en":"Leathers are leather clothes such as jackets and trousers, especially those worn by motorcyclists.","ex":{"en":"...a couple of youths in motorcyclists' black leathers.","cn":"两个穿黑色机车皮衣的年轻人"}}]},"examples":[{"en":"The soles are made of leather.","cn":"鞋底是皮革做的。"},{"en":"a leather-bound book","cn":"皮面装帧的书"}]},"learning":{"media":{"uk":"media/uk/learning__gb_1.mp3","us":"media/us/learning__us_1.mp3"},"oxford":{"phon":"ˈlɜːnɪŋ","pos":"noun","senses":[{"en":"the process of learning something","cn":"学习","g":"[uncountable]","ex":{"en":"adult learning","cn":"成人学习"}},{"en":"knowledge that you get from reading and studying","cn":"知识；学问；学识","g":"[uncountable]","ex":{"en":"a woman of great learning","cn":"学识渊博的女子"}},{"en":"something that you learn, especially from your experience of working on something","cn":"经验所得；心得体会","g":"[countable]","ex":{"en":"We will be sharing key learnings from our project.","cn":"我们将分享我们项目的主要收获。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"学习","en":"Learning is the process of gaining knowledge through studying.","ex":{"en":"The brochure described the library as the focal point of learning on the campus.","cn":"这本小册子把图书馆形容为校园学习的中心。"}}]},"examples":[{"en":"Last season was a learning experience for me.","cn":"上个季度对我来说是一次学习。"},{"en":"computer-assisted learning","cn":"计算机辅助学习"}]},"lest":{"media":{"uk":"media/uk/lest__gb_1.mp3","us":"media/us/lest__us_1.mp3"},"oxford":{"phon":"lest","pos":"conjunction","senses":[{"en":"in order to prevent something from happening","cn":"免得；以免","ex":{"en":"He gripped his brother's arm lest he be trampled by the mob.","cn":"他紧抓着他弟弟的胳膊，怕他让暴民踩着。"}},{"en":"used to introduce the reason for the particular emotion mentioned","cn":"（用于引出产生某种情感的原因）唯恐，担心","ex":{"en":"She was afraid lest she had revealed too much.","cn":"她担心她泄露得太多了。"}}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"唯恐；免得","en":"If you do something lest something unpleasant should happen, you do it to try to prevent the unpleasant thing from happening.","ex":{"en":"I was afraid to open the door lest he should follow me","cn":"我不敢开门，唯恐他还跟着我。"}}]},"examples":[{"en":"He gripped his brother's arm lest he be trampled by the mob.","cn":"他紧抓着他弟弟的胳膊，怕他让暴民踩着。"},{"en":"She was afraid lest she had revealed too much.","cn":"她担心她泄露得太多了。"}]},"lent":{"oxford":{"phon":"lent","pos":"noun","senses":[{"en":"the period of 40 days from Ash Wednesday to the day before Easter, traditionally a time of fasting (= giving up food or certain types of food), prayer and giving to charity","cn":"大斋期，四旬期（从圣灰日至复活节前一日，共 40 天）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（基督徒在复活节前作40天斋戒的）大斋期，四旬期","en":"Lent is the period of forty days before Easter, during which some Christians give up something that they enjoy.","ex":{"en":"It was a favourite meal on Fridays and fast days, particularly during Lent.","cn":"到了星期五和斋戒日、尤其是大斋期时，这个菜式非常受欢迎。"}}]},"media":{"uk":"media/uk/lent__gb_2.mp3","us":"media/us/lent__us_2.mp3"}},"learn":{"media":{"uk":"media/uk/learn__gb_1.mp3","us":"media/us/learn__us_1.mp3"},"oxford":{"phon":"lɜːn","pos":"verb","senses":[{"en":"to gain knowledge or skill by studying, from experience, from being taught, etc.","cn":"学；学习；学到；学会","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"to learn a language/skill/trade","cn":"学习一种语言／一项技能／一门手艺"}},{"en":"to study and repeat something in order to be able to remember it","cn":"记住；背熟；熟记","g":"[transitive]","ex":{"en":"I learnt the poem by heart.","cn":"我把这首诗背下来了。"}},{"en":"to gradually change your attitudes about something so that you behave in a different way","cn":"认识到；意识到；（从…）吸取教训","g":"[intransitive, transitive]","ex":{"en":"Some people never learn, do they?","cn":"有些人从来不学习，是不是？"}},{"en":"to become aware of something by hearing about it from somebody else","cn":"听到；得知；获悉","g":"[intransitive, transitive]","ex":{"en":"I first learnt of his death many years later.","cn":"许多年后我才第一次得知他的死讯。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"学；学习","en":"If you learn something, you obtain knowledge or a skill through studying or training.","ex":{"en":"Their children were going to learn English","cn":"他们的小孩会学英语。"}},{"pos":"VERB 动词","cn":"获悉；得知","en":"If you learn of something, you find out about it.","ex":{"en":"It was only after his death that she learned of his affair with Betty","cn":"一直到他死后她才知道他和贝蒂有染。"}},{"pos":"VERB 动词","cn":"学会（以某种方式行事或反应）","en":"If people learn to behave or react in a particular way, they gradually start to behave in that way as a result of a change in attitudes.","ex":{"en":"You have to learn to face your problem","cn":"你要学会面对自己的问题。"}},{"pos":"VERB 动词","cn":"（从…中）吸取（教训）","en":"If you learn from an unpleasant experience, you change the way you behave so that it does not happen again or so that, if it happens again, you can deal with it better.","ex":{"en":"I am convinced that he has learned from his mistakes","cn":"我深信他已从错误中吸取了教训。"}},{"pos":"VERB 动词","cn":"熟记；记住；背下","en":"If you learn something such as a poem or a role in a play, you study or repeat the words so that you can remember them.","ex":{"en":"He learned this song as an inmate at a Texas prison.","cn":"他在得克萨斯监狱服刑时学会了这首歌。"}},{"pos":"","cn":"","en":"to learn something the hard way→see: ; to learn the ropes→see: ;"}]},"examples":[{"en":"You can learn a great deal just from watching other players.","cn":"你只要注意看其他运动员怎么做就能学到许多东西。"},{"en":"It has been learned that 500 jobs are to be lost at the factory.","cn":"据悉工厂将要裁减 500 个工作岗位。"}]},"learned":{"media":{"uk":"media/uk/learned__gb_1.mp3","us":"media/us/learned__us_1.mp3"},"oxford":{"phon":"ˈlɜːnɪd","pos":"adjective","senses":[{"en":"having a lot of knowledge because you have studied and read a lot","cn":"有学问的；知识渊博的；博学的","lab":"formal","ex":{"en":"a learned professor","cn":"学识渊博的教授"}},{"en":"connected with or for people who have a lot of knowledge; showing and expressing deep knowledge","cn":"（为）学者的；学术性的；学问精深的","lab":"formal","ex":{"en":"a learned journal","cn":"学术性刊物"}},{"en":"developed by training or experience; not existing at birth","cn":"通过训练（或经历）形成的；学到的；非天生的","ex":{"en":"a learned skill","cn":"学来的技能"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"学识渊博的；博学的","en":"A learned person has gained a lot of knowledge by studying.","ex":{"en":"He is a serious scholar, a genuinely learned man.","cn":"他是一位严谨的学者，一个真正的学问家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（书或论文）学者（撰写）的，学问精深的；学术性的","en":"Learned books or papers have been written by someone who has gained a lot of knowledge by studying.","ex":{"en":"This learned book should start a real debate on Western policy towards the Baltics.","cn":"这部学术性著作应该会引发一场关于西方对波罗的海国家政策的大辩论。"}},{"pos":"ADJ 形容词","cn":"后天的；通过学习（或经验）获得的","en":"A learned reaction, response, or ability is one that you acquire from experience or from your environment, not one that you were born with.","ex":{"en":"Your anxiety is a learned reaction, and it is nurtured and sustained by the events of your everyday life.","cn":"人的焦虑是后天反应，由日常生活中的事件催生和维系。"}}]},"examples":[{"en":"a learned professor","cn":"学识渊博的教授"},{"en":"a learned journal","cn":"学术性刊物"}]},"leisurely":{"media":{"uk":"media/uk/leisurely__gb_1.mp3","us":"media/us/leisurely__us_1.mp3"},"oxford":{"phon":"ˈleʒəli","pos":"adjective","senses":[{"en":"done without hurrying","cn":"不慌不忙的；慢悠悠的","ex":{"en":"a leisurely meal","cn":"悠闲的一餐"}},{"en":"without hurrying","cn":"不慌不忙；从容","ex":{"en":"Couples strolled leisurely along the beach.","cn":"一对对情侣沿着沙滩漫步。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"悠闲的；从容的；慢悠悠的","en":"A leisurely action is done in a relaxed and unhurried way.","ex":{"en":"Lunch was a leisurely affair","cn":"午饭吃得很悠闲。"}}]},"examples":[{"en":"Couples strolled leisurely along the beach.","cn":"成双成对的情侣沿着海滩悠然漫步。"},{"en":"They set off at a leisurely pace.","cn":"他们步态悠闲地出发了。"}]},"leash":{"media":{"uk":"media/uk/leash__gb_1.mp3","us":"media/us/leash__us_1.mp3"},"oxford":{"phon":"liːʃ","pos":"noun","senses":[{"en":"a long piece of leather, chain or rope used for holding and controlling a dog","cn":"（牵狗用的）皮带，链条，绳索","ex":{"en":"All dogs must be kept on a leash in public places.","cn":"在公共场所所有的狗必须用绳牵住。"}},{"en":"to control an animal, especially a dog, with a leash","cn":"用皮带等系住，拴住（尤指狗）","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（牵狗的）皮带，链条","en":"A dog's leash is a long thin piece of leather or a chain, which you attach to the dog's collar so that you can keep the dog under control.","ex":{"en":"All dogs in public places should be on a leash.","cn":"在公共场所所有的狗都应该用皮带牵住。"}}]},"examples":[{"en":"All dogs must be kept on a leash in public places.","cn":"在公共场所所有的狗必须用皮带牵住。"},{"en":"At her side on a leash trotted a small grey dog.","cn":"一只用绳子牵着的灰色小狗在她的身边小跑着。"}]},"lesson":{"media":{"uk":"media/uk/lesson__gb_1.mp3","us":"media/us/lesson__us_1.mp3"},"oxford":{"phon":"ˈlesn","pos":"noun","senses":[{"en":"a period of time in which somebody is taught something","cn":"一节课；一课时","lab":"especially British English","ex":{"en":"She gives piano lessons.","cn":"她教授钢琴课。"}},{"en":"something that is intended to be learned","cn":"课；教学单元","ex":{"en":"The coursebook is divided into 30 lessons.","cn":"这本教科书分为 30 课。"}},{"en":"an experience, especially an unpleasant one, that somebody can learn from so that it does not happen again in the future","cn":"经验；教训","ex":{"en":"The accident taught me a lesson I'll never forget.","cn":"那事故给我的教训我永远也不会忘记。"}},{"en":"a passage from the Bible that is read to people during a church service in the Church of England","cn":"（英国国教会教堂礼拜中的）《圣经》选读","lab":"old-fashioned","ex":{"en":"The first lesson is taken from St John’s Gospel.","cn":"第一段圣经选自《约翰福音》。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"课程；一堂课","en":"A lesson is a fixed period of time when people are taught about a particular subject or taught how to do something.","ex":{"en":"It would be his last French lesson for months","cn":"这将是他以后几个月里的最后一堂法语课。"}},{"pos":"N-COUNT 可数名词","cn":"教训；经验","en":"You use lesson to refer to an experience which acts as a warning to you or an example from which you should learn.","ex":{"en":"There's still one lesson to be learned from the crisis—we all need to better understand the thinking of the other side.","cn":"从这次危机中我们还可以吸取一个教训——我们都需要更好地了解对方的想法。"}},{"pos":"N-COUNT 可数名词","cn":"（教堂礼拜中的）《圣经》选读","en":"In a church service, the lesson is a short piece of text which is read aloud from the bible.","ex":{"en":"The Rev. Nicola Judd read the lesson.","cn":"尼古拉·贾德牧师选读了经文。"}}]},"examples":[{"en":"Other countries can teach us a lesson or two on industrial policy.","cn":"其他国家的工业政策，我们可以借鉴一二。"},{"en":"All new students are given lessons in/on how to use the library.","cn":"所有新生都要上如何利用图书馆的课。"}]},"lectures":{"oxford":{"phon":"ˈlektʃə(r)","pos":"noun","senses":[{"en":"a talk that is given to a group of people to teach them about a particular subject, often as part of a university or college course （","cn":"通常指大学里的）讲座，讲课，演讲"},{"en":"a long angry talk that sb gives to one person or a group of people because they have done sth wrong （","cn":"冗长的）教训，训斥，谴责"}]},"media":{"uk":"media/uk/lecture__gb_1.mp3","us":"media/us/lecture__us_1.mp3"}},"leaves":{"media":{"uk":"media/uk/leaves__gb_1.mp3","us":"media/us/leaves__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"（leaf的复数和leave的第三人称单数）","en":"Leaves is the plural form of leaf, and the third person singular form of leave."}]}},"left":{"media":{"uk":"media/uk/left__gb_2.mp3","us":"media/us/left__us_2.mp3"},"oxford":{"phon":"left","pos":"adjective","senses":[{"en":"on the side of your body that is towards the west when you are facing north","cn":"左边的","lab":"sport","ex":{"en":"Fewer people write with their left hand than with their right.","cn":"用左手写字的人比用右手的人少。"}},{"en":"on or to the left side","cn":"在左边；向左","ex":{"en":"Turn left at the intersection.","cn":"在路口左转。"},"pos":"adverb"},{"en":"the left side or direction","cn":"左边；左方；左","g":"[singular]","ex":{"en":"Take the next road on the left.","cn":"在下一个路口向左拐。"},"pos":"noun"},{"en":"the first, second, etc. road on the left side","cn":"左边的（第一条、第二条等）路","g":"[singular]","ex":{"en":"Take the first left.","cn":"在下一个路口向左转。"},"pos":"noun"},{"en":"a turn to the left","cn":"左转弯","g":"[singular]","lab":"North American English also","ex":{"en":"Take a left onto Route 130.","cn":"左转弯进入 130 号公路。"},"pos":"noun"},{"en":"political groups who support the ideas and beliefs of socialism; the part of a political party whose members are most in favour of social change","cn":"（政治团体）左派；（政党内的）激进派，激进分子","g":"[singular + singular or plural verb]","ex":{"en":"The Left only has/have a small chance of winning power.","cn":"左派取得政权的机会渺茫。"},"pos":"noun"},{"en":"a hard hit that is made with your left hand","cn":"左手拳","g":"[countable]","ex":{"en":"He hit him with two sharp lefts.","cn":"他给了他两记猛烈的左手拳。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"剩余的；剩下的；余下的","en":"If there is a certain amount of something left, or if you have a certain amount of it left, it remains when the rest has gone or been used.","ex":{"en":"Is there any gin left?","cn":"还有杜松子酒吗？"}},{"pos":"N-SING 单数名词","cn":"左；左边；左面；左侧","en":"The left is one of two opposite directions, sides, or positions. If you are facing north and you turn to the left, you will be facing west. In the word 'to', the 't' is to the left of the 'o'.","ex":{"en":"In Britain cars drive on the left.","cn":"在英国，汽车靠左行驶。"}},{"pos":"ADJ 形容词","cn":"左边的；左面的；左侧的；用在左边的","en":"Your left arm, leg, or ear, for example, is the one which is on the left side of your body. Your left shoe or glove is the one which is intended to be worn on your left foot or hand."},{"pos":"N-SING-COLL 单数集合名词","cn":"左派；左翼","en":"You can refer to people who support the political ideals of socialism as the left. They are often contrasted with the right, who support the political ideals of capitalism and conservatism.","ex":{"en":"...the traditional parties of the Left","cn":"传统的左翼政党"}},{"pos":"N-SING 单数名词","cn":"左派（或激进）立场","en":"If you say that a person or political party has moved to the left, you mean that their political beliefs have become more left-wing.","ex":{"en":"After Mrs Thatcher's first election victory in 1979, Labour moved sharply to the left","cn":"1979年撒切尔夫人首次大选获胜后，工党的路线明显左转。"}}]},"examples":[{"en":"Fewer people write with their left hand than with their right.","cn":"用左手写字的人比用右手的人少。"},{"en":"Look left and right before you cross the road.","cn":"左右看一看，然后再过马路。"}]},"lend":{"oxford":{"phon":"lend","pos":"verb","senses":[{"en":"to give something to somebody or allow them to use something that belongs to you, which they have to return to you later","cn":"借给；借出","g":"[transitive]","ex":{"en":"They will lend equipment free of charge.","cn":"他们将免费借用设备。"}},{"en":"to give money to somebody on condition that they pay it back over a period of time and pay interest on it","cn":"（向…）贷（款）","g":"[transitive, intransitive]","ex":{"en":"The bank lends money at very cheap rates.","cn":"银行以非常便宜的利率放贷。"}},{"en":"to give a particular quality to a person or a situation","cn":"给…增加，增添（特色）","g":"[transitive]","lab":"formal","ex":{"en":"The setting sun lent an air of melancholy to the scene.","cn":"落日给景色增添了伤感的气氛。"}},{"en":"to give or provide help, support, etc.","cn":"给予，提供（帮助、支持等）","g":"[transitive]","ex":{"en":"I was more than happy to lend my support to such a good cause.","cn":"我非常乐意给这样崇高的事业提供援助。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"借（钱）(给…)；（银行）货（款）","en":"When people or organizations such as banks lend you money, they give it to you and you agree to pay it back at a future date, often with an extra amount as interest.","ex":{"en":"The bank is reassessing its criteria for lending money","cn":"银行正重新评估其贷款标准。"}},{"pos":"VERB 动词","cn":"借出；把…借给","en":"If you lend something that you own, you allow someone to have it or use it for a period of time.","ex":{"en":"Will you lend me your jacket for a little while?","cn":"你能把上衣借给我穿一会儿吗？"}},{"pos":"VERB 动词","cn":"提供，给予（支持）","en":"If you lend your support to someone or something, you help them with what they are doing or with a problem that they have.","ex":{"en":"He was approached by the organisers to lend support to a benefit concert","cn":"主办方找过他，希望他能对慈善音乐会给予支持。"}},{"pos":"VERB 动词","cn":"使适合；使有帮助；使易遭受","en":"If something lends itself to a particular activity or result, it is easy for it to be used for that activity or to achieve that result.","ex":{"en":"The room lends itself well to summer eating with its light, airy atmosphere.","cn":"这个房间又亮堂又通风，夏天在此用餐最合适不过。"}},{"pos":"VERB 动词","cn":"平添；增添；赋予","en":"If something lends a particular quality to something else, it adds that quality to it.","ex":{"en":"Enthusiastic applause lent a sense of occasion to the proceedings","cn":"热烈的掌声给活动平添了几分隆重的色彩。"}},{"pos":"","cn":"","en":"to lend an ear→see: ; to lend a hand→see: ; to lend your name to something→see: ;"}]},"media":{"uk":"media/uk/lend__gb_1.mp3","us":"media/us/lend__us_1.mp3"},"examples":[{"en":"I was more than happy to lend my support to such a good cause.","cn":"我非常乐意给这样崇高的事业提供援助。"},{"en":"Her presence lent the occasion a certain dignity.","cn":"她的出席使那场面增添了几分光彩。"}]},"least":{"media":{"uk":"media/uk/least__gb_1.mp3","us":"media/us/least__us_1.mp3"},"oxford":{"phon":"liːst","pos":"determiner, pronoun","senses":[{"en":"smallest in size, amount, degree, etc.","cn":"最小的；最少的；程度最轻的","ex":{"en":"He's the best teacher, even though he has the least experience.","cn":"他虽然经验最少，却是最出色的老师。"}},{"en":"to the smallest degree","cn":"最小；最少；微不足道","ex":{"en":"He always turns up just when you least expect him.","cn":"他总是在你最意料不到的时候出现。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"（数量）至少，不少于","en":"You use at least to say that a number or amount is the smallest that is possible or likely and that the actual number or amount may be greater. The forms at the least and at the very least are also used.","ex":{"en":"...a dinner menu featuring at least 15 different sorts of fish","cn":"至少列有15道不同做法的鱼的菜单"}},{"pos":"PHRASE 短语","cn":"（表示真实性或可能性）至少，最不济","en":"You use at least to say that something is the minimum that is true or possible. The forms at the least and at the very least are also used.","ex":{"en":"She could take a nice holiday at least","cn":"最不济她也可以去过一个愉快的假期。"}},{"pos":"PHRASE 短语","cn":"（表示相对于不利条件或糟糕情形）起码，不管怎样","en":"You use at least to indicate an advantage that exists in spite of the disadvantage or bad situation that has just been mentioned.","ex":{"en":"We've no idea what his state of health is but at least we know he is still alive","cn":"我们不清楚他的健康情况如何，但起码知道他仍然活着。"}},{"pos":"PHRASE 短语","cn":"（表示更正或改变自己刚说过的话）至少，起码","en":"You use at least to indicate that you are correcting or changing something that you have just said.","ex":{"en":"It's not difficult to get money for research or at least it's not always difficult","cn":"争取到研究资金并不难，起码不总是那么难。"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"最少的","en":"You use the least to mean a smaller amount than anyone or anything else, or the smallest amount possible.","ex":{"en":"I try to offend the least amount of people possible","cn":"我尽量少得罪人。"}},{"pos":"PRON 代词","cn":"","en":"Least is also a pronoun.","ex":{"en":"On education funding, Japan performs best but spends the least per student.","cn":"在教育投资方面，日本花在每位学生身上的钱最少，但却做得最好。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"（某一特性）最少，最缺","en":"You use least to indicate that someone or something has less of a particular quality than most other things of its kind.","ex":{"en":"The least experienced athletes had caused a great many false-starts through the day's proceedings","cn":"那天的比赛中，经验最浅的运动员抢跑无数次。"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"丝毫的；一丁点儿的","en":"You use the least to emphasize the smallness of something, especially when it hardly exists at all.","ex":{"en":"I don't have the least idea of what you're talking about","cn":"我一点儿都不知道你在说什么。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"（程度）最小","en":"You use least to indicate that something is true or happens to a smaller degree or extent than anything else or at any other time.","ex":{"en":"He had a way of throwing her off guard with his charm when she least expected it.","cn":"他往往趁她最没有心理准备时发动魅力攻势，令她措手不及。"}},{"pos":"ADJ-SUPERL 形容词最高级形式","cn":"无足轻重的；微乎其微的","en":"You use least in structures where you are emphasizing that a particular situation or event is much less important or serious than other possible or actual ones.","ex":{"en":"Having to get up at three o'clock every morning was the least of her worries","cn":"她发愁的事多着呢，相比之下，每天早上3点就要起床根本就不算什么。"}},{"pos":"PRON 代词","cn":"（应该做的）最少量，最低程度","en":"You use the least in structures where you are stating the minimum that should be done in a situation, and suggesting that more should really be done.","ex":{"en":"Well, the least you can do, if you won't help me yourself, is to tell me where to go instead","cn":"你自己要是不帮我，好歹也告诉我该上哪儿去呀。"}},{"pos":"PHRASE 短语","cn":"丝毫；一点儿","en":"You can use in the least and the least bit to emphasize a negative.","ex":{"en":"I'm not like that at all. Not in the least","cn":"我哪里是那种人。绝对不是。"}},{"pos":"PHRASE 短语","cn":"最后不能不提；最后但同样重要的是","en":"You use last but not least to say that the last person or thing to be mentioned is as important as all the others.","ex":{"en":"...her four sons, Christopher, twins Daniel and Nicholas, and last but not least 2-year-old Jack.","cn":"她的4个儿子，克里斯托弗、双胞胎丹尼尔和尼古拉斯，还有不能不提的两岁大的杰克"}},{"pos":"PHRASE 短语","cn":"（用于否定句后）（多者之中）尤其，尤数","en":"You can use least of all after a negative statement to emphasize that it applies especially to the person or thing mentioned.","ex":{"en":"No one ever reads these articles, least of all me","cn":"从没有人读这些文章，我就更不用说了。"}},{"pos":"PHRASE 短语","cn":"（强调某一例证或原因）尤其是，特别是，相当重要地","en":"You can use not least to emphasize a particularly important example or reason.","ex":{"en":"Dieting can be bad for you, not least because it is a cause of stress","cn":"节食可能不利于健康，相当重要的原因是它会引起精神压力。"}},{"pos":"PHRASE 短语","cn":"轻则；往轻里说；客气点说","en":"You can use to say the least to suggest that a situation is actually much more extreme or serious than you say it is.","ex":{"en":"Accommodation was basic to say the least","cn":"往轻里说是住宿条件简陋。"}}]},"examples":[{"en":"The documentary caused a lot of bad feeling, not least among the workers whose lives it described.","cn":"那部纪录片引起了许多人的反感，尤其是在片中描写到其生活的工人。"},{"en":"‘Do you mind if I put the television on?’ ‘No, not in the least.’ “","cn":"我开电视机你介意吗？” “不，一点也不介意。”"}]},"legion":{"media":{"uk":"media/uk/legion__gb_1.mp3","us":"media/us/legion__us_1.mp3"},"oxford":{"phon":"ˈliːdʒən","pos":"noun","senses":[{"en":"a large group of soldiers that forms part of an army, especially the one that existed in ancient Rome","cn":"（尤指古罗马的）军团","ex":{"en":"the French Foreign Legion","cn":"法国外籍军团"}},{"en":"a large number of people of one particular type","cn":"大量，大批（某类型的人）","lab":"formal","ex":{"en":"legions of photographers","cn":"众多的摄影师"}},{"en":"very many","cn":"大量；很多","ex":{"en":"The medical uses of herbs are legion.","cn":"草本植物的医药效用数不胜数。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"军团；兵团","en":"A legion is a large group of soldiers who form one section of an army.","ex":{"en":"...the Sudan-based troops of the Libyan Islamic Legion","cn":"利比亚伊斯兰军团驻扎在苏丹的部队"}},{"pos":"N-COUNT 可数名词","cn":"众多；大批；大量","en":"A legion of people or things is a great number of them.","ex":{"en":"His delightful sense of humour won him a legion of friends.","cn":"他的幽默风趣为他赢得了众多的朋友。"}},{"pos":"ADJ 形容词","cn":"比比皆是的；不胜枚举的；多如牛毛的","en":"If you say that things of a particular kind are legion, you mean that there are a great number of them.","ex":{"en":"Ellie's problems are legion","cn":"埃莉的问题多如牛毛。"}}]},"examples":[{"en":"The medical uses of herbs are legion.","cn":"草本植物的医药效用数不胜数。"},{"en":"the French Foreign Legion","cn":"法国军队中的外籍军团"}]},"ledger":{"media":{"uk":"media/uk/ledger__gb_1.mp3","us":"media/us/ledger__us_1.mp3"},"oxford":{"phon":"ˈledʒə(r)","pos":"noun","senses":[{"en":"a book or electronic document in which a bank, a business, etc. records the money it has paid and received","cn":"收支总账；分类账簿；分户账簿","ex":{"en":"to enter figures in the purchase/sales ledger","cn":"把金额录入购货／销售分类账"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"总账；账簿；账本","en":"A ledger is a book in which a company or organization writes down the amounts of money it spends and receives."}]},"examples":[{"en":"to enter figures in the purchase/sales ledger","cn":"把金额输入购货/销售分类账"}]},"lens":{"media":{"uk":"media/uk/lens__gb_1.mp3","us":"media/us/lens__us_1.mp3"},"oxford":{"phon":"lenz","pos":"noun","senses":[{"en":"a curved piece of glass or plastic that makes things look larger, smaller or clearer when you look through it","cn":"透镜；镜片","ex":{"en":"a pair of glasses with tinted lenses","cn":"一副有色镜片眼镜"}},{"en":"a piece of equipment that is part of a camera, containing one or more lenses","cn":"（相机的）镜头","ex":{"en":"a camera with an adjustable lens","cn":"带有可调镜头的照相机"}},{"en":"a contact lens (= a small round piece of thin plastic that you put on your eye to help you see better)","cn":"隐形眼镜","lab":"informal","ex":{"en":"Have you got your lenses in?","cn":"你戴了隐形眼镜吗？"}},{"en":"the clear part of the eye, behind the pupil, that focuses light so that you can see clearly","cn":"（眼球的）晶状体","lab":"anatomy"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"透镜；镜片","en":"A lens is a thin curved piece of glass or plastic used in things such as cameras, telescopes, and pairs of glasses. You look through a lens in order to make things look larger, smaller, or clearer.","ex":{"en":"...a camera lens","cn":"照相机镜头"}},{"pos":"N-COUNT 可数名词","cn":"（眼球的）晶状体","en":"In your eye, the lens is the part behind the pupil that focuses light and helps you to see clearly."}]},"examples":[{"en":"a camera with an adjustable lens","cn":"带有可调镜头的照相机"},{"en":"Have you got your lenses in?","cn":"你戴了隐形眼镜吗？"}]},"length":{"media":{"uk":"media/uk/length__gb_1.mp3","us":"media/us/length__us_1.mp3"},"oxford":{"phon":"leŋkθ","pos":"noun","senses":[{"en":"the size or measurement of something from one end to the other","cn":"长；长度","g":"[uncountable, countable]","sc":"size/measurement","ex":{"en":"Measure the length of the line from A to B.","cn":"测量从 A 到 B 的线段的长度。"}},{"en":"the quality of being long","cn":"长","g":"[uncountable]","sc":"size/measurement","ex":{"en":"Did you see the length of his hair?","cn":"你看见他头发有多长吗？"}},{"en":"the amount of time that something lasts","cn":"时长","g":"[uncountable, countable]","sc":"time","ex":{"en":"The average length of each song on the album is six minutes.","cn":"专辑中每首歌的平均时长是 6 分钟。"}},{"en":"the amount of writing in a book, or a document, etc.; the amount of time that a film lasts","cn":"篇幅；长度","g":"[countable, uncountable]","sc":"of book/film","ex":{"en":"There is a maximum length of 2 500 words.","cn":"最多不超过 2 500 字。"}},{"en":"having the length mentioned","cn":"有…长度的","sc":"-length","ex":{"en":"shoulder-length hair","cn":"齐肩长发"}},{"en":"the distance from one end of a swimming pool to the other","cn":"游泳池长度（一端至另一端的距离）","g":"[countable]","sc":"of swimming pool","ex":{"en":"He swims 50 lengths a day.","cn":"他每天游 50 个游泳池那么长的距离。"}},{"en":"the size of a horse or boat from one end to the other, when it is used to measure the distance between two horses or boats taking part in a race","cn":"（马或船的）自身长度","g":"[countable]","sc":"in race","ex":{"en":"The horse won by two clear lengths.","cn":"那匹马以整整领先两个马身的优势获胜。"}},{"en":"a long, thin piece of something","cn":"细长的一段（或一节、一根等）","g":"[countable]","sc":"long thin piece","ex":{"en":"a length of rope/string/wire","cn":"一根绳子／细线／金属线"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"长度；距离","en":"The length of something is the amount that it measures from one end to the other along the longest side.","ex":{"en":"It is about a metre in length.","cn":"它长约1米。"}},{"pos":"N-VAR 可变名词","cn":"（文章等的）篇幅","en":"The length of something such as a piece of writing is the amount of writing that is contained in it.","ex":{"en":"...a book of at least 100 pages in length","cn":"一百多页厚的书"}},{"pos":"N-VAR 可变名词","cn":"（持续）时间的长短","en":"The length of an event, activity, or situation is the period of time from beginning to end for which something lasts or during which something happens.","ex":{"en":"The exact length of each period may vary","cn":"每一阶段的确切时长可能会有所不同。"}},{"pos":"N-COUNT 可数名词","cn":"（绳、布、木头等的）一段，一节，一截","en":"A length of rope, cloth, wood, or other material is a piece of it that is intended to be used for a particular purpose or that exists in a particular situation.","ex":{"en":"...a 30ft length of rope","cn":"一根30英尺长的绳子"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（与短相对的）长","en":"The length of something is its quality of being long.","ex":{"en":"Many have been surprised at the length of time it has taken him to make up his mind","cn":"他居然花了那么长时间才拿定主意，许多人都对此感到吃惊。"}},{"pos":"N-COUNT 可数名词","cn":"（游泳池的）池长","en":"If you swim a length in a swimming pool, you swim the distance from one end to the other.","ex":{"en":"I swim 40 lengths a day.","cn":"我每天游20个来回。"}},{"pos":"N-COUNT 可数名词","cn":"（赛艇中的）艇位；（赛马中的）马位，马身长度","en":"In boat racing or horse racing, a length is the distance from the front to the back of the boat or horse. You can talk about one boat or horse being one or more lengths in front of or behind another.","ex":{"en":"Harvard won by four lengths.","cn":"哈佛大学队领先4个艇位胜出。"}},{"pos":"N-SING 单数名词","cn":"全程；全长","en":"If something happens or exists along the length of something, it happens or exists for the whole way along it.","ex":{"en":"I looked along the length of the building","cn":"我的目光沿着大楼从首到尾扫过。"}},{"pos":"PHRASE 短语","cn":"终究；终归；最终","en":"If someone does something at length, they do it after a long period of time.","ex":{"en":"At length my father went into the house.","cn":"我父亲最后还是进了屋。"}},{"pos":"PHRASE 短语","cn":"长久地；详尽地","en":"If someone does something at length, they do it for a long time or in great detail.","ex":{"en":"They spoke at length, reviewing the entire incident.","cn":"他们把事情的整个经过详尽地复述了一遍。"}},{"pos":"PHRASE 短语","cn":"不遗余力；竭尽全力；千方百计","en":"If you say that someone goes to great lengths to achieve something, you mean that they try very hard and perhaps do extreme things in order to achieve it.","ex":{"en":"Greta Garbo went to great lengths to hide from reporters and photographers.","cn":"葛丽泰·嘉宝想方设法躲开记者和摄影师。"}},{"pos":"","cn":"","en":"at arm's length→see: ; the length and breadth of→see: ;"}]},"examples":[{"en":"Size of pension depends partly on length of service with the company.","cn":"退休金的多少部分取决于为公司服务时间的长短。"},{"en":"He swims 50 lengths a day.","cn":"他每天游 50 个游泳池那么长的距离。"}]},"leap":{"media":{"uk":"media/uk/leap__gb_1.mp3","us":"media/us/leap__us_1.mp3"},"oxford":{"phon":"liːp","pos":"verb","senses":[{"en":"to jump high or a long way","cn":"跳；跳跃；跳越","g":"[intransitive, transitive]","ex":{"en":"A dolphin leapt out of the water.","cn":"海豚跃出水面。"}},{"en":"to move or do something suddenly and quickly","cn":"猛冲；突然做（某事）","g":"[intransitive]","lab":"figurative","ex":{"en":"She leapt out of bed.","cn":"她突然翻身下了床。"}},{"en":"to increase suddenly and by a large amount","cn":"骤增；剧增；猛涨","g":"[intransitive]","ex":{"en":"The shares leapt in value from 476p to close at 536p.","cn":"股价从 476 便士猛涨到收盘时的 536 便士。"}},{"en":"a long or high jump","cn":"跳越；跳跃；跳高","lab":"figurative","ex":{"en":"a leap of six metres","cn":"一跳跳了六米"},"pos":"noun"},{"en":"a sudden large increase in something","cn":"急剧上升；飙升；猛增","ex":{"en":"a leap in profits","cn":"利润跃升"},"pos":"noun"},{"en":"a sudden change from one thing to another; very fast progress with something","cn":"快速转型；突变；飞跃","ex":{"en":"Few people successfully make the leap from television to the movies.","cn":"很少有人从电视业成功转向电影业。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"纵身；跳；跃","en":"If you leap, you jump high in the air or jump a long distance.","ex":{"en":"He had leapt from a window in the building and escaped","cn":"他从大楼一个窗口跳出去跑了。"}},{"pos":"VERB 动词","cn":"迅捷地移动","en":"If you leap somewhere, you move there suddenly and quickly.","ex":{"en":"The two men leaped into the jeep and roared off","cn":"两名男子跳上吉普车，疾驰而去。"}},{"pos":"VERB 动词","cn":"（车辆）飞奔，疾驶","en":"If a vehicle leaps somewhere, it moves there in a short sudden movement.","ex":{"en":"The car leapt forward.","cn":"汽车向前飞驰。"}},{"pos":"N-COUNT 可数名词","cn":"骤变；激增；飞跃","en":"A leap is a large and important change, increase, or advance.","ex":{"en":"The result has been a giant leap in productivity.","cn":"其结果是生产力的大幅提高。"}},{"pos":"VERB 动词","cn":"骤变；激增；飞跃","en":"If you leap to a particular place or position, you make a large and important change, increase, or advance.","ex":{"en":"Warwicks leap to third in the table, 31 points behind leaders Essex.","cn":"沃里克队在排名中蹿升至第3名，落后领先的埃塞克斯队31分。"}},{"pos":"VERB 动词","cn":"（因吃惊、害怕、高兴等心脏）猛地跳动","en":"If you say that your heart leaps, you mean that you experience a sudden, very strong feeling of surprise, fear, or happiness.","ex":{"en":"My heart leaped at the sight of her.","cn":"我见到她时心都要跳出来了。"}},{"pos":"VERB 动词","cn":"赶紧抓住（机会）","en":"If you leap at a chance or opportunity, you accept it quickly and eagerly.","ex":{"en":"The post of principal of the theatre school became vacant and he leapt at the chance.","cn":"戏剧学校校长一职出缺，他马上抓住了这个机会。"}},{"pos":"PHRASE 短语","cn":"（改善或增长）非常迅速地，飞跃地","en":"You can use in leaps and bounds or by leaps and bounds to emphasize that someone or something is improving or increasing quickly and greatly.","ex":{"en":"He's improved in leaps and bounds this season","cn":"他今季的表现一日千里。"}},{"pos":"PHRASE 短语","cn":"冒险举动；瞎闯","en":"If you take a leap in the dark or a leap into the unknown, you do something without having any previous experience in that activity or knowledge of it.","ex":{"en":"Prudent people are not going to take a leap in the dark","cn":"小心谨慎的人是不会轻易冒险的。"}}]},"examples":[{"en":"The shares leapt in value from 476p to close at 536p.","cn":"股价从 476 便士猛涨到收盘时的 536 便士。"},{"en":"( figurative ) Few people successfully make the leap from television to the movies.","cn":"从电视业转向电影业很少有人成功。"}]},"less":{"media":{"uk":"media/uk/less__gb_1.mp3","us":"media/us/less__us_1.mp3"},"oxford":{"phon":"les","pos":"determiner, pronoun","senses":[{"en":"used with uncountable nouns to mean ‘a smaller amount of’","cn":"（与不可数名词连用）较少的，更少的","ex":{"en":"less butter/time/importance","cn":"较少的黄油／时间；次要"}},{"en":"without","cn":"无；没有","ex":{"en":"treeless","cn":"没有树木的"},"pos":"suffix"},{"en":"not doing; not affected by","cn":"不做；不受影响","ex":{"en":"tireless","cn":"孜孜不倦的"},"pos":"suffix"},{"en":"to a smaller degree; not so much","cn":"较少；较小；没那么多；少","ex":{"en":"less expensive/likely/intelligent","cn":"价钱较便宜；可能性较小；智力较差"},"pos":"adverb"},{"en":"used before a particular amount that must be taken away from the amount just mentioned","cn":"减去；扣除","ex":{"en":"a monthly salary of $2 000 less tax and insurance","cn":"月薪 2 000 美元，未扣税和保险费"},"pos":"preposition"}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"（数量）较小（或少）的；更小（或少）的（前面可用a little，a lot，a bit，far和much等修饰）","en":"You use less to indicate that there is a smaller amount of something than before or than average. You can use 'a little', 'a lot', 'a bit', 'far', and 'much' in front of less.","ex":{"en":"People should eat less fat to reduce the risk of heart disease.","cn":"人们应该减少脂肪摄入，以降低患心脏病的危险。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（用在数字或数量前）少于，低于，比…少","en":"You use less than before a number or amount to say that the actual number or amount is smaller than this.","ex":{"en":"Motorways actually cover less than 0.1 percent of the countryside","cn":"高速公路的实际覆盖面积还不到农村地区的0.1%。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"（某一特性的程度与以往或一般情况相比）较轻地，较差地","en":"You use less to indicate that something or someone has a smaller amount of a quality than they used to or than is average or usual.","ex":{"en":"I often think about those less fortunate than me","cn":"我经常想到那些没我这么幸运的人。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"不像…（更像…）；与其说…（倒不如说…）","en":"If you say that something is less one thing than another, you mean that it is like the second thing rather than the first.","ex":{"en":"At first sight it looked less like a capital city than a mining camp","cn":"乍看上去，它不像是首府，更像是矿工村。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"（做得）较少，更少","en":"If you do something less than before or less than someone else, you do it to a smaller extent or not as often.","ex":{"en":"We are eating more and exercising less","cn":"我们吃得多了，锻炼却少了。"}},{"pos":"PHR-CONJ-COORD","cn":"（用于否定句后）遑论，更何况，更不用说","en":"You use the expressions still less ,much less, and even less after a negative statement in order to introduce and emphasize a further statement, and to make it negative too.","ex":{"en":"I never talked about it, still less about her","cn":"我从来没说起过这事，更没有提起过她。"}},{"pos":"PREP 介词","cn":"（用在数字或数量前）扣除，减去","en":"When you are referring to amounts, you use less in front of a number or quantity to indicate that it is to be subtracted from another number or quantity already mentioned.","ex":{"en":"...Boyton Financial Services Fees: £750, less £400","cn":"博伊顿金融服务费：750英镑，扣除400英镑"}},{"pos":"PHRASE 短语","cn":"逐渐减少；越来越小","en":"You use less and less to say that something is becoming smaller all the time in degree or amount.","ex":{"en":"The couple seem to spend less and less time together","cn":"两口子在一起的时间似乎越来越少。"}},{"pos":"PHRASE 短语","cn":"毫不；完全不；一点都不","en":"You use less than to say that something does not have a particular quality. For example, if you describe something as less than perfect, you mean that it is not perfect at all.","ex":{"en":"Her greeting was less than enthusiastic","cn":"她的问候一点都不热情。"}},{"pos":"PHRASE 短语","cn":"（对某事物或某人的重要性表示惊讶或钦佩）竟然，居然","en":"You can use no less as a way of expressing surprise or admiration at the importance of something or someone.","ex":{"en":"He had returned to England in an aircraft carrier no less","cn":"他竟然坐航空母舰回的英格兰。"}},{"pos":"PHRASE 短语","cn":"（对某一数目之大表示惊奇）多达","en":"You use no less than before an amount to indicate that the amount is larger than you expected.","ex":{"en":"No less than 35 per cent of the country is protected in the form of parks and nature sanctuaries","cn":"该国多达35%的地区以公园和自然保护区的形式受到保护。"}},{"pos":"","cn":"","en":"couldn't care less→see: ; more or less→see: ; nothing less than→see: ;"}]},"examples":[{"en":"The guide contains details of no less than 115 hiking routes.","cn":"这本导游指南包括多达 115 条徒步旅行路线的详细介绍。"},{"en":"That this is a positive stereotype makes it no less a stereotype, and therefore unacceptable.","cn":"这种成见即使是积极的也不失之为成见，因而是不可取的。"}]},"lengthy":{"media":{"uk":"media/uk/lengthy__gb_1.mp3","us":"media/us/lengthy__us_1.mp3"},"oxford":{"phon":"ˈleŋkθi","pos":"adjective","senses":[{"en":"very long, and often too long, in time or size","cn":"很长的；漫长的；冗长的","ex":{"en":"lengthy delays","cn":"多次长时间拖延"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漫长的；冗长的；长期的","en":"You use lengthy to describe an event or process which lasts for a long time.","ex":{"en":"...a lengthy meeting.","cn":"冗长的会议"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（报告、文章等）长篇大论的，冗长的","en":"A lengthy report, article, book, or document contains a lot of speech, writing, or other material.","ex":{"en":"...a lengthy report from the Council of Ministers","cn":"部长会议发布的冗长报告"}}]},"examples":[{"en":"the lengthy process of obtaining a visa","cn":"取得签证的漫长过程"},{"en":"lengthy delays","cn":"多次长时间拖延"}]},"leopards":{"oxford":{"phon":"ˈlepəd","pos":"noun","senses":[{"en":"a large animal of the cat family, that has yellowish-brown fur with black spots. Leopards live in Africa and southern Asia.","cn":"豹"},{"en":"( saying ) people cannot change their character, especially if they have a bad character","cn":"本性难改；禀性难移"}]},"media":{"uk":"media/uk/leopard__gb_1.mp3","us":"media/us/leopard__us_1.mp3"}},"lemon":{"media":{"img":["media/ldoce/img/lemon.jpg","media/pic/citrus_fruits_comp.jpg"],"uk":"media/uk/lemon__gb_1.mp3","us":"media/us/lemon__us_1.mp3"},"oxford":{"phon":"ˈlemən","pos":"noun","senses":[{"en":"a yellow citrus fruit with juice that has a bitter, sharp taste. Slices of lemon and lemon juice are used in cooking and drinks.","cn":"柠檬","g":"[countable, uncountable]","ex":{"en":"Add a squeeze of lemon juice.","cn":"挤入一点柠檬汁。"}},{"en":"lemon juice or a drink made from lemon","cn":"柠檬汁；柠檬饮料","g":"[uncountable, countable]"},{"en":"a pale yellow colour","cn":"浅黄色；柠檬色","g":"[uncountable]"},{"en":"a thing that cannot be used because it does not work as it should","cn":"无用的东西；蹩脚货；废品","g":"[countable]","lab":"especially North American English, informal，，"},{"en":"a stupid person","cn":"笨蛋；傻瓜","g":"[countable]","lab":"British English"},{"en":"pale yellow in colour","cn":"浅黄色的；柠檬色的","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"柠檬","en":"A lemon is a bright yellow fruit with very sour juice. Lemons grow on trees in warm countries.","ex":{"en":"...a slice of lemon.","cn":"一片柠檬"}},{"pos":"N-UNCOUNT 不可数名词","cn":"柠檬汁；柠檬味饮料","en":"Lemon is a drink that tastes of lemons."},{"pos":"COLOUR 颜色词","cn":"同lemon yellow","en":"Lemon is the same as lemon yellow ."},{"pos":"N-COUNT 可数名词","cn":"蹩脚货；次品","en":"If you think that something is a failure, or not as good or as useful as it should be, you can say that it is a lemon .","ex":{"en":"He took a little test drive and agreed the car was a lemon.","cn":"他试驾了一下，也认为这车不行。"}},{"pos":"N-COUNT 可数名词","cn":"傻乎乎的人；棒槌","en":"If you think that someone looks foolish because they are shy or slow to take action, you can say that they are like a lemon .","ex":{"en":"I just stood there like a lemon.","cn":"我就傻乎乎地站在那儿。"}}]},"examples":[{"en":"a gin and tonic with ice and lemon","cn":"一杯加冰和柠檬的杜松子酒奎宁水"},{"en":"Squeeze the juice of half a lemon over the fish.","cn":"把半个柠檬的汁挤在鱼上。"}]},"ledge":{"media":{"uk":"media/uk/ledge__gb_1.mp3","us":"media/us/ledge__us_1.mp3"},"oxford":{"phon":"ledʒ","pos":"noun","senses":[{"en":"a narrow, flat piece of rock that sticks out from a cliff","cn":"悬崖岩石突出部；岩架","ex":{"en":"seabirds nesting on rocky ledges","cn":"在岩架上筑巢的海鸟"}},{"en":"a narrow flat shelf fixed to a wall, especially one below a window","cn":"（平窄的）壁架，横档；（尤指）窗台","ex":{"en":"She put the vase of flowers on the window ledge.","cn":"她把那瓶花放在窗台上。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（位于山崖边向外平伸的）岩架，岩脊","en":"A ledge is a piece of rock on the side of a cliff or mountain, which is in the shape of a narrow shelf."},{"pos":"N-COUNT 可数名词","cn":"窗台","en":"A ledge is a narrow shelf along the bottom edge of a window.","ex":{"en":"She had climbed onto the ledge outside his window.","cn":"她爬到了他窗外的窗台上。"}}]},"examples":[{"en":"She put the vase of flowers on the window ledge.","cn":"她把那瓶花放在窗台上。"},{"en":"seabirds nesting on rocky ledges","cn":"在岩架上筑巢的海鸟"}]},"lettuce":{"oxford":{"phon":"ˈletɪs","pos":"noun","senses":[{"en":"a plant with large green leaves that are eaten raw, especially in salad. There are many types of lettuce.","cn":"莴苣；生菜","ex":{"en":"a bacon, lettuce and tomato sandwich","cn":"培根生菜番茄三明治"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"莴苣；生菜","en":"A lettuce is a plant with large green leaves that is the basic ingredient of many salads."}]},"media":{"img":["media/ldoce/img/lettuce.jpg","media/pic/salad_vegetables_comp.jpg"],"uk":"media/uk/lettuce__gb_1.mp3","us":"media/us/lettuce__us_1.mp3"},"examples":[{"en":"a bacon, lettuce and tomato sandwich","cn":"咸肉、生菜加番茄三明治"},{"en":"Buy a lettuce and some tomatoes.","cn":"买一个生菜和一些番茄。"}]},"left-justify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使左对齐","en":"If printed text is left-justified, each line begins at the same distance from the left-hand edge of the page or column.","ex":{"en":"The data in the cells should be left-justified.","cn":"单元格里的数据应该靠左对齐。"}}]}},"leaning":{"media":{"uk":"media/uk/leaning__gb_1.mp3","us":"media/us/leaning__us_1.mp3"},"oxford":{"phon":"ˈliːnɪŋ","pos":"noun","senses":[{"en":"a feeling that makes you tend to prefer something or to believe in particular ideas, opinions, etc.","cn":"倾向；偏向；爱好","ex":{"en":"My leanings have always been towards comedy rather than tragedy.","cn":"我一直倾向于喜剧而不是悲剧。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"倾向；偏向；爱好","en":"Your particular leanings are the beliefs, ideas, or aims you hold or a tendency you have towards them.","ex":{"en":"During the war his pacifist leanings were not helpful.","cn":"战时他的和平主义思想派不上用场。"}}]},"examples":[{"en":"a leaning towards comedy rather than tragedy","cn":"偏爱喜剧而不是悲剧"},{"en":"a person with socialist leanings","cn":"具有社会主义倾向的人"}]},"leading":{"media":{"uk":"media/uk/leading__gb_1.mp3","us":"media/us/leading__us_1.mp3"},"oxford":{"phon":"ˈliːdɪŋ","pos":"adjective","senses":[{"en":"most important or most successful","cn":"最重要的；一流的","ex":{"en":"a leading expert/authority/figure/member","cn":"一流专家／权威／人物／成员"}},{"en":"ahead of others in a race or contest","cn":"（赛跑或比赛中）领先的，最前的","ex":{"en":"She started the last lap just behind the leading group.","cn":"她开始跑最后一圈时紧跟在领先的一组人后面。"}},{"en":"the amount of white space between lines of printed text","cn":"行距（印刷文本两行之间的距离）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最重要的；卓著的；显赫的","en":"The leading person or thing in a particular area is the one which is most important or successful.","ex":{"en":"...a leading member of Bristol's Sikh community","cn":"布里斯托尔锡克教社群一位出类拔萃的成员"}},{"pos":"ADJ 形容词","cn":"主角的；主演的","en":"The leading role in a play or film is the main role. A leading lady or man is an actor who plays this role."},{"pos":"ADJ 形容词","cn":"（在比赛或行列中）首位的，居前的","en":"The leading group, vehicle, or person in a race or procession is the one that is at the front."}]},"examples":[{"en":"She started the last lap just behind the leading group.","cn":"她开始跑最后一圈时紧跟在领先的一组人后面。"},{"en":"She was offered the leading role in the new TV series.","cn":"她获得主演那部新的电视连续剧的机会。"}]},"lep":{"oxford":{"phon":"ˌel iː ˈpiː","pos":"abbreviation","senses":[{"en":"Limited English Proficient or Limited English Proficiency (used to describe students who cannot speak English very well)","cn":"英语水平有限的（用于描述英语口语不够流利的学生）","ex":{"en":"schools with large numbers of LEP children","cn":"有很多英语水平有限的学童的学校"}}]},"media":{"uk":"media/uk/lep_1_gb_1.mp3","us":"media/us/lep_1_us_1.mp3"},"examples":[{"en":"schools with large numbers of LEP children","cn":"有很多英语水平有限的学童的学校"},{"en":"The number of LEP students has risen since 1993.","cn":"从1993年起﹐英语水平有限的学生人数有所增加。"}]},"league":{"media":{"uk":"media/uk/league__gb_1.mp3","us":"media/us/league__us_1.mp3"},"oxford":{"phon":"liːɡ","pos":"noun","senses":[{"en":"a group of sports teams who all play each other to earn points and find which team is best","cn":"（体育运动队的）联合会，联赛","ex":{"en":"Castleford have led the league for most of the season.","cn":"卡斯尔福德这个赛季的大部分时间里领跑联赛。"}},{"en":"a level of quality, ability, etc.","cn":"（质量、能力等的）等级，级别，水平","lab":"informal","ex":{"en":"As a painter, he is in a league of his own (= much better than others).","cn":"作为画家，他独领风骚。"}},{"en":"a group of people or nations who have combined for a particular purpose","cn":"联盟；同盟","ex":{"en":"the League of Nations","cn":"国际联盟"}},{"en":"a unit for measuring distance, equal to about 3 miles or 4 000 metres","cn":"里格（长度单位，约等于 3 英里或 4 000 米）","lab":"old use"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"联盟；同盟","en":"A league is a group of people, clubs, or countries that have joined together for a particular purpose, or because they share a common interest.","ex":{"en":"...the League of Nations.","cn":"国际联盟"}},{"pos":"N-COUNT 可数名词","cn":"（体育运动队的）联合会，联赛","en":"A league is a group of teams that play the same sport or activity against each other.","ex":{"en":"...the American League series between the Boston Red Sox and World Champion Oakland Athletics","cn":"波士顿红袜队和世界大赛冠军奥克兰运动家队的美国联盟冠军赛对决"}},{"pos":"N-COUNT 可数名词","cn":"级别；档次；水平","en":"You use the word league to make comparisons between different people or things, especially in terms of their quality.","ex":{"en":"Her success has taken her out of my league","cn":"她的成绩令我望尘莫及。"}},{"pos":"PHRASE 短语","cn":"沆瀣一气；勾结","en":"If you say that someone is in league with another person to do something bad, you mean that they are working together to do that thing.","ex":{"en":"There is no evidence that the broker was in league with the fraudulent vendor","cn":"没有证据表明该经纪人与进行诈骗的卖主狼狈为奸。"}}]},"examples":[{"en":"A house like that is out of our league (= too expensive for us).","cn":"那样的房子不是我们这号人买得起的。"},{"en":"When it comes to cooking, I'm not in her league (= she is much better than me).","cn":"提到烹饪，我的水平远比不上她。"}]},"lead-up":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"先声；前导；前奏","en":"The lead-up to an event is the things connected to that event that happen before it.","ex":{"en":"The lead-up to the wedding was extremely interesting.","cn":"婚礼的前奏非常有意思。"}}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41lead-up.mp3","us":"media/ldoce/hwd/ame/6/ld41lead-up.mp3"},"examples":[{"en":"the lead-up to the election","cn":"大选的筹备工作"}]},"let's":{"media":{"uk":"media/uk/let_s_1_gb_1.mp3","us":"media/us/let_s_1_us_1.mp3"},"oxford":{"phon":"lets","pos":"short form","senses":[{"en":"let us","cn":"让我们"}]},"collins":{"senses":[{"pos":"","cn":"(let us的常用口语形式）","en":"Let's is the usual spoken form of 'let us'."}]},"examples":[{"en":"Let's break for lunch.","cn":"咱们停下来吃午饭吧。"},{"en":"Let’s go!","cn":"我们走吧！"}]},"lecture":{"media":{"uk":"media/uk/lecture__gb_1.mp3","us":"media/us/lecture__us_1.mp3"},"oxford":{"phon":"ˈlektʃə(r)","pos":"noun","senses":[{"en":"a talk that is given to a group of people to teach them about a particular subject, often as part of a university or college course","cn":"（通常指大学里的）讲座，讲课，演讲","lab":"British English","ex":{"en":"to go to/attend a lecture","cn":"去听讲座"}},{"en":"a long, angry talk that somebody gives to one person or a group of people because they have done something wrong","cn":"（冗长的）教训，训斥，谴责","ex":{"en":"I know I should stop smoking—don't give me a lecture about it.","cn":"我知道我该戒烟，别再教训我了。"}},{"en":"to give a talk or a series of talks to a group of people on a subject, especially as a way of teaching in a university or college","cn":"（尤指在大学里）开讲座，讲授，讲课","g":"[intransitive]","ex":{"en":"He has taught and lectured at the University of Pretoria.","cn":"他曾在比勒陀利亚大学授课。"},"pos":"verb"},{"en":"to criticize somebody or tell them how you think they should behave, especially when it is done in an annoying way","cn":"（尤指恼人地）指责，训斥，告诫","g":"[transitive]","ex":{"en":"Don’t start lecturing me!","cn":"别教训我呀！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指大学或学院里的）演讲，讲座，讲课","en":"A lecture is a talk someone gives in order to teach people about a particular subject, usually at a university or college.","ex":{"en":"...a series of lectures by Professor Eric Robinson","cn":"埃里克·鲁宾逊教授的系列讲座"}},{"pos":"VERB 动词","cn":"（就…）作演讲（或讲座）","en":"If you lecture on a particular subject, you give a lecture or a series of lectures about it.","ex":{"en":"She then invited him to Atlanta to lecture on the history of art","cn":"她于是邀请他去亚特兰大讲艺术史。"}},{"pos":"VERB 动词","cn":"训诫；教训","en":"If someone lectures you about something, they criticize you or tell you how they think you should behave.","ex":{"en":"He used to lecture me about getting too much sun","cn":"他以前常唠叨我太阳晒得太多。"}}]},"examples":[{"en":"to attend a series of lectures on Jane Austen","cn":"听关于简 · 奥斯汀的系列讲座"},{"en":"I know I should stop smoking — don't give me a lecture about it.","cn":"我知道我该戒烟，别再教训我了。"}]},"learns":{"oxford":{"phon":"lɜːn","pos":"verb","senses":[{"en":"to gain knowledge or skill by studying, from experience, from being taught, etc.","cn":"学；学习；学到；学会"},{"en":"to become aware of sth by hearing about it from sb else","cn":"听到；得知；获悉"}]},"media":{"uk":"media/uk/learn__gb_1.mp3","us":"media/us/learn__us_1.mp3"}},"lemma":{"oxford":{"phon":"ˈlemə","pos":"noun","senses":[{"en":"a statement that is assumed to be true in order to test the truth of another statement","cn":"引理；辅助定理","lab":"specialist"},{"en":"the basic form of a word, for example the singular form of a noun or the infinitive form of a verb, as it is shown at the beginning of a dictionary entry","cn":"词根，词元（词的基本形式，如名词单数或动词的不定式形式）","lab":"linguistics"}]},"media":{"uk":"media/uk/lemma__gb_1.mp3","us":"media/us/lemma__us_1.mp3"}},"letting":{"media":{"uk":"media/uk/letting__gb_1.mp3","us":"media/us/letting__us_1.mp3"},"oxford":{"phon":"ˈletɪŋ","pos":"noun","senses":[{"en":"an act of renting out a house or other property to somebody else; a house or property that you rent out","cn":"（房屋等不动产的）出租；出租的房屋（或其他不动产）","ex":{"en":"holiday lettings","cn":"假日出租房"}}]},"examples":[{"en":"holiday lettings","cn":"假日出租"},{"en":"short-term holiday lettings","cn":"短期出租的度假房屋"}]},"letter":{"media":{"uk":"media/uk/letter__gb_1.mp3","us":"media/us/letter__us_1.mp3"},"oxford":{"phon":"ˈletə(r)","pos":"noun","senses":[{"en":"a written, typed or printed message that is put in an envelope or attached to an email and sent to somebody","cn":"信；信件；电邮","lab":"British English","ex":{"en":"to write/send (somebody) a letter","cn":"给（某人）写信／寄信"}},{"en":"a written or printed sign representing a sound used in speech","cn":"字母","ex":{"en":"‘B’ is the second letter of the alphabet.","cn":"b 是字母表的第二个字母。"}},{"en":"a sign in the shape of a letter that is sewn onto clothes to show that a person plays in a school or college sports team","cn":"（缝制在运动服上的）校运动队字母标志","lab":"North American English"},{"en":"to give a letter to something as part of a series or list","cn":"用字母标明（于清单等上）","g":"[transitive, usually passive]","ex":{"en":"the stars lettered Alpha and Beta","cn":"以 α 和 β 命名的星"},"pos":"verb"},{"en":"to print, paint, sew, etc. letters onto something","cn":"把字母印刷（或缝制等）于","g":"[transitive, usually passive]","ex":{"en":"a black banner lettered in white","cn":"印有白色字母的黑色横幅"},"pos":"verb"},{"en":"to receive a letter made of cloth that you sew onto your clothes for playing in a school or college sports team","cn":"领取到学校运动队布制字母标志","g":"[intransitive]","lab":"North American English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"信;信函","en":"If you write a letter to someone, you write a message on paper and send it to them, usually by post.","ex":{"en":"I had received a letter from a very close friend.","cn":"我收到一个很要好的朋友的来信。"}},{"pos":"N-COUNT 可数名词","cn":"字母","en":"Letters are written symbols which represent one of the sounds in a language.","ex":{"en":"...the letters of the alphabet.","cn":"字母表中的字母"}},{"pos":"N-COUNT 可数名词","cn":"（校队队衣的）校名首字母标志（以嘉许优秀运动员）","en":"If a student earns a letter in sports or athletics by being part of the university or college team, they are entitled to wear on their jacket the initial letter of the name of their university or college.","ex":{"en":"Valerie earned letters in three sports: volleyball, basketball, and field hockey.","cn":"瓦莱丽在排球、篮球和曲棍球三个项目上获得了佩戴校名首字母标志的荣誉。"}},{"pos":"VERB 动词","cn":"赢得佩戴校名首字母标志的荣誉","en":"If a student letters in sports or athletics by being part of the university or college team, they are entitled to wear on their jacket the initial letter of the name of their university or college.","ex":{"en":"Burkoth lettered in soccer.","cn":"伯考思在足球上获得了佩戴校名首字母标志的荣誉。"}},{"pos":"PHRASE 短语","cn":"（钻）法律字眼","en":"If you say that someone keeps to the letter of the law, you mean that they act according to what is actually written in the law, rather than according to the general principles of it, especially when you disapprove of this.","ex":{"en":"They had stuck to the letter of the law and in my view they should be ashamed.","cn":"他们死抠法律字眼。依我看他们应该感到惭愧。"}},{"pos":"PHRASE 短语","cn":"（执行指示）毫厘不爽地，不折不扣地","en":"If you say that someone carries out instructions to the letter, you mean that they do exactly what they are told to do, paying great attention to every detail.","ex":{"en":"She obeyed his instructions to the letter.","cn":"她分毫不差地遵照他的吩咐去做。"}}]},"examples":[{"en":"They insist on sticking to the letter of the law.","cn":"他们坚持严守法律的字面意义。"},{"en":"I followed your instructions to the letter.","cn":"我是严格遵照你的指示办的。"}]},"legislation":{"oxford":{"phon":"ˌledʒɪsˈleɪʃn","pos":"noun","senses":[{"en":"a law or a set of laws passed by a parliament","cn":"法规；法律","lab":"especially North American English","ex":{"en":"an important piece of legislation","cn":"一条重要的法规"}},{"en":"the process of making and passing laws","cn":"立法；制定法律","ex":{"en":"Legislation will be difficult and will take time.","cn":"立法既费力又耗时。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"法律；法规","en":"Legislation consists of a law or laws passed by a government.","ex":{"en":"...a letter calling for legislation to protect women's rights.","cn":"一封呼吁立法保护妇女权益的信"}}]},"media":{"uk":"media/uk/legislation__gb_1.mp3","us":"media/us/legislation__us_1.mp3"},"examples":[{"en":"New legislation on the sale of drugs will be introduced next year.","cn":"有关药物销售的新法规将于明年出台。"},{"en":"Legislation will be difficult and will take time.","cn":"立法既费力又耗时。"}]},"leopard":{"media":{"uk":"media/uk/leopard__gb_1.mp3","us":"media/us/leopard__us_1.mp3","img":["media/ldoce/img/leopard.jpg"]},"oxford":{"phon":"ˈlepəd","pos":"noun","senses":[{"en":"a large animal of the cat family, usually with yellow-brown fur with black spots. Leopards live in Africa and southern Asia.","cn":"豹"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"豹","en":"A leopard is a type of large, wild cat. Leopards have yellow fur and black spots, and live in Africa and Asia."},{"pos":"PHRASE 短语","cn":"本性难移；陋习难改","en":"If you say that a leopard cannot change its spots, you mean that people or things are not able to change their basic characteristics, especially when you are critical of those characteristics.","ex":{"en":"This only goes to show how this racist leopard has in no way changed his spots.","cn":"这恰恰说明了这个种族主义分子的本性从未改变过。"}}]}},"led":{"media":{"uk":"media/uk/led__gb_2.mp3","us":"media/us/led__us_2.mp3"},"oxford":{"phon":"led","pos":"","senses":[{"en":"influenced or organized by","cn":"起主导作用的","ex":{"en":"a consumer-led society","cn":"消费者主导的社会"}},{"en":"light-emitting diode (a device that produces a light on electrical and electronic equipment)","cn":"发光二极管","ex":{"en":"A single red LED shows that the power is switched on.","cn":"单支红色发光二极管表示电源已接通。"},"pos":"noun"}]},"examples":[{"en":"A single red LED shows that the power is switched on.","cn":"单支红色发光二极管表示电源已接通。"}],"collins":{"senses":[{"pos":"","cn":"","en":"Led is the past tense and past participle of lead."}]}},"lead":{"media":{"uk":"media/uk/lead__gb_1.mp3","us":"media/us/lead__us_1.mp3","img":["media/ldoce/img/pencil.jpg"]},"oxford":{"phon":"liːd","pos":"verb","senses":[{"en":"to go with or in front of a person or an animal to show the way or to make them go in the right direction","cn":"带路；领路；引领","g":"[intransitive, transitive]","lab":"figurative","sc":"show the way","ex":{"en":"If you lead, I'll follow.","cn":"你领头，我跟着。"}},{"en":"to connect one object or place to another","cn":"（与…）相连，相通","g":"[intransitive]","sc":"connect two things","ex":{"en":"steps leading from the kitchen to the cellar","cn":"从厨房到地窖的台阶"}},{"en":"to go in a particular direction or to a particular place","cn":"通向；通往","g":"[intransitive, transitive]","lab":"figurative","sc":"of road/path/door","ex":{"en":"A path led down the hill.","cn":"有一条小路通往山下。"}},{"en":"to have something as a result","cn":"导致，造成（后果）","g":"[intransitive]","sc":"cause","ex":{"en":"The carbon tax will inevitably lead to an increase in energy bills.","cn":"碳税将不可避免地导致能源费用的增加。"}},{"en":"to be the reason why somebody does or thinks something","cn":"使得出（观点）；引导（某人）","g":"[transitive]","sc":"cause","ex":{"en":"What led you to this conclusion?","cn":"你是如何得出这个结论的？"}},{"en":"to be in control of something; to be the leader of something","cn":"控制；掌管；领导；率领","g":"[transitive, intransitive]","sc":"be in control","ex":{"en":"to lead a team/group","cn":"领导一个团队／小组"}},{"en":"to be the best at something; to be in first place","cn":"最擅长于；处于首位；处于领先地位","g":"[transitive, intransitive]","sc":"be best/first","ex":{"en":"The department led the world in cancer research.","cn":"这个系在癌症研究方面走在了世界前列。"}},{"en":"to have a particular type of life","cn":"过（某种生活）","g":"[transitive]","sc":"life","ex":{"en":"We lead a very quiet life.","cn":"我们过着非常平静的生活。"}},{"en":"to cause a process to start","cn":"启动；带动","g":"[transitive]","sc":"process","ex":{"en":"The recent economic recovery was almost entirely led by exports.","cn":"近期的经济复苏几乎完全由出口带动。"}},{"en":"to play first; to play something as your first card","cn":"开牌；率先出牌","g":"[intransitive, transitive]","sc":"in card games","ex":{"en":"It's your turn to lead.","cn":"轮到你开牌了。"}},{"en":"the position ahead of everyone else in a race or competition","cn":"（竞赛中的）领先地位","g":"[singular]","sc":"first place","ex":{"en":"She took the lead in the second lap.","cn":"她在第二圈时取得领先。"},"pos":"noun"},{"en":"the amount or distance that somebody/something is in front of somebody/something else","cn":"超前量；领先的距离","g":"[singular]","sc":"first place","ex":{"en":"a commanding/comfortable lead","cn":"遥遥／轻松领先"},"pos":"noun"},{"en":"an example or action for people to copy","cn":"实例；范例；榜样","g":"[singular]","sc":"example","ex":{"en":"If one bank raises interest rates, all the others will follow their lead.","cn":"要是有一家银行提高利率，所有其他银行都会效法。"},"pos":"noun"},{"en":"a piece of information that may help to find out the truth or facts about a situation, especially a crime","cn":"（尤指有关犯罪的）线索","g":"[countable]","sc":"information","ex":{"en":"The police will follow up all possible leads.","cn":"警方将追踪所有可能有用的线索。"},"pos":"noun"},{"en":"a person or thing that may be useful to you, especially a possible new customer or business opportunity","cn":"潜在客户；可能业务","g":"[countable]","sc":"in business","ex":{"en":"The marketing campaign generated hundreds of new leads.","cn":"营销活动赢得了数百名新的潜在客户。"},"pos":"noun"},{"en":"the main part in a play, film, etc.; the person who plays this part","cn":"（戏剧、电影等中的）主角，主演","g":"[countable]","sc":"actor/musician","ex":{"en":"Who is playing the lead?","cn":"谁是主演？"},"pos":"noun"},{"en":"the person in charge of a project, department, etc.","cn":"（项目、部门等的）负责人","g":"[countable]","sc":"person in charge","ex":{"en":"Sam is the lead on this project.","cn":"萨姆是这个项目的负责人。"},"pos":"noun"},{"en":"the first sentence or paragraph of a news story, giving the most important points of the story","cn":"（新闻报道的）导语","g":"[countable]","lab":"US English","sc":"news","ex":{"en":"Check out this lead from Monday's front page story:…","cn":"查看周一头版报道的线索：……"},"pos":"noun"},{"en":"a long piece of leather, chain or rope used for holding and controlling a dog","cn":"（牵狗用的）皮带，链条，绳索","g":"[countable]","lab":"British English","sc":"for dog","ex":{"en":"Dogs must be kept on a lead in the park.","cn":"狗在公园里必须系着牵狗带。"},"pos":"noun"},{"en":"a long piece of wire, usually covered in plastic, that is used to connect a piece of electrical equipment to a source of electricity","cn":"电线；导线","g":"[countable]","lab":"British English","sc":"for electricity","pos":"noun"},{"en":"a chemical element. Lead is a heavy, soft grey metal, used especially in the past for water pipes or to cover roofs.","cn":"铅","g":"[uncountable]","ex":{"en":"Lead exposure can be harmful to everyone, especially young children and babies.","cn":"铅接触会伤害到每一个人，尤其是幼童和婴儿。"},"pos":"noun"},{"en":"the thin black part of a pencil that marks paper","cn":"铅笔芯","g":"[countable, uncountable]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"在…前面走（或骑）；为…带头","en":"If you lead a group of people, you walk or ride in front of them.","ex":{"en":"John Major and the Duke of Edinburgh led the mourners","cn":"约翰·梅杰和爱丁堡公爵走在送葬队伍前面。"}},{"pos":"VERB 动词","cn":"给…引路（或带路）；带…（到某处）","en":"If you lead someone to a particular place or thing, you take them there.","ex":{"en":"He took Dickon by the hand to lead him into the house","cn":"他牵着迪康的手把他领进屋。"}},{"pos":"VERB 动词","cn":"（路或门）通，至，达","en":"If a road, gate, or door leads somewhere, you can get there by following the road or going through the gate or door.","ex":{"en":"...the doors that led to the yard.","cn":"通往院子的大门"}},{"pos":"VERB 动词","cn":"（在比赛或竞赛中）领先，占先","en":"If you are leading at a particular point in a race or competition, you are winning at that point.","ex":{"en":"He's leading in the presidential race","cn":"他在总统竞选中领先。"}},{"pos":"N-SING 单数名词","cn":"领先的地位；占先的位置","en":"If you have the lead or are in the lead in a race or competition, you are winning.","ex":{"en":"England took the lead after 31 minutes with a goal by Peter Nail","cn":"英格兰队第31分钟由彼得·奈尔攻进一球，取得领先。"}},{"pos":"N-SING 单数名词","cn":"超前量；领先程度","en":"Someone's lead over a competitor at a particular point in a race or competition is the distance, amount of time, or number of points by which they are ahead of them.","ex":{"en":"...a commanding lead for the opposition is clearly emerging throughout the country","cn":"显然反对党已开始在全国占据一边倒的领先地位。"}},{"pos":"VERB 动词","cn":"在…中领先；胜过；主导","en":"If one company or country leads others in a particular activity such as scientific research or business, it is more successful or advanced than they are in that activity.","ex":{"en":"When it comes to pop music we not only lead Europe, we lead the world.","cn":"我们不仅引领欧洲而且引领着全球的流行音乐潮流。"}},{"pos":"VERB 动词","cn":"领导；率领；指挥","en":"If you lead a group of people, an organization, or an activity, you are in control or in charge of the people or the activity.","ex":{"en":"He led the country between 1949 and 1984","cn":"1949到1984年间他是该国领导人。"}},{"pos":"N-COUNT 可数名词","cn":"先河；榜样；表率","en":"If you give a lead, you do something new or develop new ideas or methods that other people consider to be a good example or model to follow.","ex":{"en":"...the need for the president to give a moral lead","cn":"需要总统树立一个道德榜样"}},{"pos":"VERB 动词","cn":"过（某种生活）","en":"You can use lead when you are saying what kind of life someone has. For example, if you lead a busy life, your life is busy.","ex":{"en":"She led a normal, happy life with her sister and brother","cn":"她和弟弟妹妹一起过着平凡而幸福的生活。"}},{"pos":"VERB 动词","cn":"招致；致使；导致","en":"If something leads to a situation or event, usually an unpleasant one, it begins a process which causes that situation or event to happen.","ex":{"en":"Ethnic tensions among the republics could lead to civil war","cn":"共和国之间紧张的种族关系可能会引发内战。"}},{"pos":"VERB 动词","cn":"促使；使得；使","en":"If something leads you to do something, it influences or affects you in such a way that you do it.","ex":{"en":"His abhorrence of racism led him to write The Algiers Motel Incident","cn":"对种族主义的憎恨促使他写了《阿尔及尔汽车旅馆事件》一书。"}},{"pos":"VERB 动词","cn":"诱使；误导","en":"If you say that someone or something led you to think something, you mean that they caused you to think it, although it was not true or did not happen.","ex":{"en":"Mother had led me to believe the new baby was a kind of present for me","cn":"母亲让我相信新出生的宝宝是给我的一个礼物。"}},{"pos":"VERB 动词","cn":"引导，掌控（谈话或讨论的内容）","en":"If you lead a conversation or discussion, you control the way that it develops so that you can introduce a particular subject.","ex":{"en":"After a while I led the conversation around to her job","cn":"过了一阵子，我把话题引到她的工作上。"}},{"pos":"VERB 动词","cn":"（讨论或文章中某一观点或话题）把…带到，为…引出（另一观点或话题）","en":"You can say that one point or topic in a discussion or piece of writing leads you to another in order to introduce a new point or topic that is linked with the previous one.","ex":{"en":"Well, I think that leads me to the real point.","cn":"这个嘛，我看这让我说到正题了。"}},{"pos":"N-COUNT 可数名词","cn":"线索；头绪","en":"A lead is a piece of information or an idea which may help people to discover the facts in a situation where many facts are not known, for example in the investigation of a crime or in a scientific experiment.","ex":{"en":"The inquiry team is also following up possible leads after receiving 400 calls from the public.","cn":"在接到民众400个热线电话后，调查组亦在对可能的线索进行追踪。"}},{"pos":"N-COUNT 可数名词","cn":"（戏剧、电影等中的）主角；扮演主角的演员","en":"The lead in a play, film, or show is the most important part in it. The person who plays this part can also be called the lead.","ex":{"en":"Nina Ananiashvili and Alexei Fadeyechev from the Bolshoi Ballet dance the leads","cn":"由莫斯科大剧院芭蕾舞团的尼娜·阿纳尼阿什维利和阿列克谢·法捷耶切夫担纲演出。"}},{"pos":"N-COUNT 可数名词","cn":"狗绳；牵狗带","en":"A dog's lead is a long, thin chain or piece of leather which you attach to the dog's collar so that you can control the dog.","ex":{"en":"An older man came out with a little dog on a lead.","cn":"一个年纪较大的男子牵着一条小狗走了出来。"}},{"pos":"N-COUNT 可数名词","cn":"导线；连接线","en":"A lead in a piece of equipment is a piece of wire covered in plastic which supplies electricity to the equipment or carries it from one part of the equipment to another."},{"pos":"N-SING 单数名词","cn":"（报纸或电视、电台的）要闻，头条","en":"The lead story or lead in a newspaper or on the television or radio news is the most important story.","ex":{"en":"The Turkish situation makes the lead in tomorrow's Guardian","cn":"土耳其局势将成为明天《卫报》的头条。"}},{"pos":"See also:","cn":"","en":"→see: ; one thing led to another→see: ; to lead the way→see: ;"},{"pos":"","cn":"","en":"相关词组：lead off lead on lead on to lead up to"},{"pos":"N-UNCOUNT 不可数名词","cn":"铅","en":"Lead is a soft, grey, heavy metal.","ex":{"en":"...drinking water supplied by old-fashioned lead pipes.","cn":"由老式铅管输送的饮用水"}},{"pos":"N-UNCOUNT 不可数名词","cn":"枪弹；子弹；枪子儿","en":"Lead is sometimes used to refer to bullets.","ex":{"en":"Eventually Bogart pumps him full of lead.","cn":"最后博加特开枪扫射，把他打成了马蜂窝。"}},{"pos":"N-COUNT 可数名词","cn":"（铅笔的）笔芯","en":"The lead in a pencil is the centre part of it which makes a mark on paper."}]},"examples":[{"en":"The lead car is now three minutes ahead of the rest of the field.","cn":"现在跑在最前面的汽车较赛场上其余的赛车领先三分钟。"},{"en":"If one bank raises interest rates, all the others will follow their lead.","cn":"要是有一家银行提高利率，所有其他银行都会效法。"}]},"learner":{"media":{"uk":"media/uk/learner__gb_1.mp3","us":"media/us/learner__us_1.mp3"},"oxford":{"phon":"ˈlɜːnə(r)","pos":"noun","senses":[{"en":"a person who is finding out about a subject or how to do something","cn":"学习者","ex":{"en":"a slow/quick learner","cn":"迟钝的／聪明的学生"}},{"en":"a person who is learning to drive a car","cn":"学习驾车者；驾驶学员","lab":"British English also","ex":{"en":"Learners are not allowed to drive without a licensed driver in the vehicle.","cn":"在车内没有持照驾驶员的情况下，学员不得驾驶汽车。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"学习者；初学者","en":"A learner is someone who is learning about a particular subject or how to do something.","ex":{"en":"...a new aid for younger children or slow learners","cn":"针对年幼者和学习迟缓者的新教辅手段"}}]},"examples":[{"en":"a dictionary for learners of English","cn":"英语学习词典"},{"en":"learner-centred teaching methods","cn":"以学生为中心的教学方法"}]},"level":{"media":{"uk":"media/uk/level__gb_1.mp3","us":"media/us/level__us_1.mp3"},"oxford":{"phon":"ˈlevl","pos":"noun","senses":[{"en":"the height of something in relation to the ground or to what it used to be","cn":"（与地面或过去位置相对的）高度","g":"[countable, uncountable]","sc":"height","ex":{"en":"The cables are buried one metre below ground level.","cn":"电缆埋在地平面下一米深的地方。"}},{"en":"a floor of a building; a layer of ground","cn":"楼层；地层","g":"[countable]","sc":"floor/layer","ex":{"en":"a multi-level parking lot","cn":"多层停车场"}},{"en":"the amount of something that exists in a particular situation at a particular time","cn":"（某时某情况下存在的）数量，程度，浓度","g":"[countable]","sc":"amount","ex":{"en":"a low level of support for the proposed changes","cn":"变革动议的低支持率"}},{"en":"a particular standard or quality","cn":"标准；水平；质量；品级","g":"[countable, uncountable]","sc":"standard","ex":{"en":"The hotel's level of service is consistently high.","cn":"酒店的服务水平一直很高。"}},{"en":"a position or rank in a scale of size or importance","cn":"层次；级别","g":"[uncountable, countable]","sc":"rank in scale","ex":{"en":"the upper levels of government","cn":"上级政府"}},{"en":"a particular way of looking at, reacting to or understanding something","cn":"看待（或应对、理解）事物的方式","g":"[countable]","sc":"point of view","ex":{"en":"On a more personal level, I would like to thank Jean for all the help she has given me.","cn":"从较为个人的角度我要感谢琼所给予我的一切帮助。"}},{"en":"one of a series of stages in a computer game. Players progress from easy to more advanced levels within the game.","cn":"（电脑游戏的）级别，关卡","g":"[countable]","sc":"in computer games","ex":{"en":"a computer game with 15 levels","cn":"包含 15 个关卡的电脑游戏"}},{"en":"a device used to test whether a surface is level, consisting of a glass tube partly filled with liquid with a bubble of air inside. The position of the bubble indicates whether the surface is level.","cn":"气泡式水准仪","g":"[countable]","sc":"tool"},{"en":"having a flat surface that does not slope","cn":"平的；平坦的","sc":"flat","ex":{"en":"Pitch the tent on level ground.","cn":"把帐篷搭建在平地上。"},"pos":"adjective"},{"en":"having the same height, position, value, etc. as something","cn":"等高的；地位相同的；价值相等的","sc":"equal","ex":{"en":"Are these pictures level?","cn":"这些画挂得一样高吗？"},"pos":"adjective"},{"en":"having the same score as somebody","cn":"得分相同","lab":"especially British English, sport，，","sc":"equal","ex":{"en":"A good second round brought him level with the tournament leader.","cn":"他第二轮发挥良好，与锦标赛领先选手得分持平。"},"pos":"adjective"},{"en":"not showing any emotion; steady","cn":"平静的；冷静的；平稳的","sc":"voice/look","ex":{"en":"a level gaze","cn":"目光平静的凝视"},"pos":"adjective"},{"en":"to make something flat or smooth","cn":"使平坦；使平整","g":"[transitive]","sc":"make flat","ex":{"en":"The first coat of plaster levels out the surface of the wall.","cn":"第一层灰泥使墙面平整。"},"pos":"verb"},{"en":"to make something, especially a score in sport, equal or similar","cn":"打平，追平（尤指比分）","g":"[transitive, intransitive]","sc":"make equal","ex":{"en":"Davies levelled the score at 2 all.","cn":"戴维斯把比分拉成 2:2 平。"},"pos":"verb"},{"en":"to destroy a building or a group of trees completely by knocking it down","cn":"摧毁，夷平（建筑物或树林）","g":"[transitive]","sc":"destroy","ex":{"en":"The blast levelled several buildings in the area.","cn":"那次爆炸把当地几座建筑物夷为平地。"},"pos":"verb"},{"en":"to point something, especially a gun, at somebody","cn":"（尤指用枪）瞄准，对准","g":"[transitive]","sc":"point","ex":{"en":"I had a gun levelled at my head.","cn":"有一支枪对准了我的头。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"水平；程度；等级","en":"A level is a point on a scale, for example a scale of amount, quality, or difficulty.","ex":{"en":"If you don't know your cholesterol level, it's a good idea to have it checked","cn":"你要是不清楚自己的胆固醇水平，最好去检查一下。"}},{"pos":"N-SING 单数名词","cn":"水位；液位","en":"The level of a river, lake, or ocean or the level of liquid in a container is the height of its surface.","ex":{"en":"The water level of the Mississippi River is already 6.5 feet below normal","cn":"密西西比河的水位已经比正常值低了6.5英尺。"}},{"pos":"ADJ 形容词","cn":"（烹饪中的量）与匙口平齐的","en":"In cookery, a level spoonful of a substance such as flour or sugar is an amount that fills the spoon exactly, without going above the top edge.","ex":{"en":"Stir in 1 level teaspoon of yeast.","cn":"加入一平茶匙的酵母后搅拌。"}},{"pos":"N-SING 单数名词","cn":"高度","en":"If something is at a particular level, it is at that height.","ex":{"en":"Liz sank down until the water came up to her chin and the bubbles were at eye level.","cn":"莉兹往下沉，直到水没过下巴，泡沫浮至眼睛。"}},{"pos":"ADJ 形容词","cn":"（与…）等高的，齐平的","en":"If one thing is level with another thing, it is at the same height as it.","ex":{"en":"He leaned over the counter so his face was almost level with the boy's","cn":"他倾身伏在柜台上，一张脸几乎凑到小男孩的面前。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平的；平坦的","en":"When something is level, it is completely flat with no part higher than any other.","ex":{"en":"The floor was level, but the ceiling sloped toward his head.","cn":"地板是平的，但天花板朝他的头这边倾斜。"}},{"pos":"ADV 副词","cn":"靠近地；接近地","en":"If you draw level with someone or something, you get closer to them until you are by their side.","ex":{"en":"Just before we drew level with the gates, he slipped out of the jeep and disappeared into the crowd","cn":"我们快到门前时，他溜出吉普车，消失在人群中。"}},{"pos":"ADV 副词","cn":"（成绩或比分）扳平地，追平地","en":"If you draw level with someone, you manage to improve your performance until it is the same as theirs, by scoring the same number of points or goals as them.","ex":{"en":"Napoli have drawn level with AC Milan at the top of the Italian league.","cn":"那不勒斯队追平了AC米兰队，并列意大利联赛排行榜的榜首。"}},{"pos":"VERB 动词","cn":"扳平，拉平（成绩或比分）","en":"In sport, if a player or team levels the score, they score a goal or win some points so that their team has the same number of points or goals as the opposing team.","ex":{"en":"Iglesias scored twice to level the score","cn":"伊格莱西亚斯连进两球，追平了比分。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（语气）平稳的，平静的，不动声色的","en":"If you keep your voice level, you speak in a deliberately calm and unemotional way.","ex":{"en":"He forced his voice to remain level","cn":"他竭力使自己的语气保持平静。"}},{"pos":"VERB 动词","cn":"（人、风暴等）摧毁，夷平，荡平","en":"If someone or something such as a violent storm levels a building or area of land, they destroy it completely or make it completely flat.","ex":{"en":"Further tremors could level more buildings","cn":"余震可能会摧毁更多的建筑物。"}},{"pos":"VERB 动词","cn":"使（指责、批评等）针对；使矛头指向","en":"If an accusation or criticism is levelled at someone, they are accused of doing wrong or they are criticized for something they have done.","ex":{"en":"Allegations of corruption were levelled at him and his family","cn":"他和他的家人受到了贪污指控。"}},{"pos":"VERB 动词","cn":"使瞄准；使对准","en":"If you level an object at someone or something, you lift it and point it in their direction.","ex":{"en":"He said thousands of Koreans still levelled guns at one another along the demilitarised zone between them.","cn":"他说在非军事区两边仍然有数以千计的韩国和朝鲜军人用枪互相瞄准对方。"}},{"pos":"VERB 动词","cn":"（对某人）说实话；直言相告","en":"If you level with someone, you tell them the truth and do not keep anything secret.","ex":{"en":"I'll level with you. I'm no great detective. I've no training or anything","cn":"实话告诉你吧，我根本不是什么大侦探。我没有受过任何训练。"}},{"pos":"PHRASE 短语","cn":"竭尽所能；全力以赴","en":"If you say that you will do your level best to do something, you are emphasizing that you will try as hard as you can to do it, even if the situation makes it very difficult.","ex":{"en":"The President told American troops that he would do his level best to bring them home soon.","cn":"总统跟美军士兵说他会尽其所能让他们早日回家。"}},{"pos":"PHRASE 短语","cn":"真诚；坦率；诚恳","en":"If you say that someone or something is on the level, you mean that they are sincere or honest, and are not attempting to deceive people.","ex":{"en":"There were probably moments when you wondered if anyone spoke the truth or was on the level.","cn":"很可能有些时候你会怀疑，到底有没有人在说真话，有没有人是真诚的。"}},{"pos":"","cn":"","en":"a level playing field→see: ;"},{"pos":"","cn":"","en":"相关词组：level off level out"}]},"examples":[{"en":"This latest rise is intended to keep wages level with inflation.","cn":"最近这次加薪目的是使工资与通货膨胀保持相同的水平。"},{"en":"Teachers are accused of levelling standards down to suit the needs of less able students.","cn":"有人指责教师降低标准以适应学习较差的学生的需要。"}]},"leg":{"oxford":{"phon":"leɡ","pos":"noun","senses":[{"en":"one of the long parts that connect the feet to the rest of the body","cn":"腿","g":"[countable]","lab":"informal","sc":"part of body","ex":{"en":"Sit on the floor, stretching your legs out in front of you.","cn":"坐在地板上，将双腿伸到身前。"}},{"en":"the leg of an animal, especially the top part, cooked and eaten","cn":"（尤指供食用的）动物的腿，腿肉","g":"[countable, uncountable]","sc":"meat","ex":{"en":"Have you ever tried frogs' legs?","cn":"你尝试过青蛙腿吗？"}},{"en":"the part of a pair of trousers that covers the leg","cn":"裤腿","g":"[countable]","sc":"of trousers/pants","ex":{"en":"a trouser/pant leg","cn":"一只裤腿"}},{"en":"one of the long thin parts on the bottom of a table, chair, etc. that support it","cn":"（桌椅等的）腿","g":"[countable]","sc":"of table/chair","ex":{"en":"a table/chair leg","cn":"桌子腿；椅子腿"}},{"en":"having the number or type of legs mentioned","cn":"有…腿的","sc":"-legged","ex":{"en":"a three-legged stool","cn":"三条腿的凳子"}},{"en":"one part of a journey or race","cn":"一段路程（或赛程）","g":"[countable]","sc":"of journey/race","ex":{"en":"The final leg of the trip was by donkey.","cn":"这次旅行的最后一段是骑驴。"}},{"en":"one of a pair of matches played between the same opponents in a sports competition, which together form a single round (= stage) of the competition","cn":"（相同对手间同一回合两场比赛中的）一场","g":"[countable]","lab":"British English","sc":"sports game","ex":{"en":"The Spanish team won the third leg.","cn":"西班牙队在第三回合领先。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腿","en":"A person or animal's legs are the long parts of their body that they use to stand on.","ex":{"en":"He was tapping his walking stick against his leg.","cn":"他用手杖轻敲着腿。"}},{"pos":"N-COUNT 可数名词","cn":"（裤）腿","en":"The legs of a pair of trousers are the parts that cover your legs.","ex":{"en":"He moved on through wet grass that soaked his trouser legs.","cn":"他继续前行，穿过湿漉漉的草地，裤腿全湿透了。"}},{"pos":"N-COUNT 可数名词","cn":"（供食用动物的）腿肉","en":"A leg of lamb, pork, chicken, or other meat is a piece of meat that consists of the animal's or bird's leg, especially the thigh.","ex":{"en":"...a chicken leg.","cn":"鸡腿"}},{"pos":"N-COUNT 可数名词","cn":"（桌、椅等家具的）腿，脚","en":"The legs of a table, chair, or other piece of furniture are the parts that rest on the floor and support the furniture's weight.","ex":{"en":"His ankles were tied to the legs of the chair","cn":"他的脚脖子被绑在椅腿上。"}},{"pos":"N-COUNT 可数名词","cn":"一段路程；一段旅程","en":"A leg of a long journey is one part of it, usually between two points where you stop.","ex":{"en":"The first leg of the journey was by boat to Lake Naivasha in Kenya.","cn":"行程的首段是乘船到肯尼亚的奈瓦沙湖。"}},{"pos":"N-COUNT 可数名词","cn":"（系列赛中的）一场，一轮，一段","en":"A leg of a sports competition is one of a series of games that are played to find an overall winner.","ex":{"en":"The first round of the cup was decided over two legs","cn":"杯赛的首轮以两场分胜负。"}},{"pos":"PHRASE 短语","cn":"快跑；（尤指）逃开","en":"If you leg it, you run very quickly, usually in order to escape from someone.","ex":{"en":"We saw some kids shinning up a drainpipe before legging it clutching a TV and hi-fi","cn":"我们看见几个年轻人爬上了排水管，后来就见他们提着一台电视机和音响跑掉了。"}},{"pos":"PHRASE 短语","cn":"大势已去；玩儿完；没戏","en":"If you say that something or someone is on their last legs, you mean that the period of time when they were successful or strong is ending.","ex":{"en":"This relationship is on its last legs.","cn":"这段关系已经快玩儿完了。"}},{"pos":"PHRASE 短语","cn":"戏弄；捉弄","en":"If you are pulling someone's leg, you are teasing them by telling them something shocking or worrying as a joke.","ex":{"en":"Of course I won't tell them; I was only pulling your leg.","cn":"我当然不会告诉他们啦。我跟你开玩笑的。"}},{"pos":"PHRASE 短语","cn":"能够证实/无法证实；站得住脚/站不住脚","en":"If you say that someone does not have a leg to stand on, or hasn't got a leg to stand on, you mean that a statement or claim they have made cannot be justified or proved.","ex":{"en":"It's only my word against his, I know. So I don't have a leg to stand on.","cn":"现在是我和他各说各的，这我知道。所以我的话无法证实。"}},{"pos":"PHRASE 短语","cn":"有持久力；有潜力","en":"If an idea, plan, or activity has legs, it is likely to continue or succeed.","ex":{"en":"The American economy still has legs.","cn":"美国经济仍可持续发展。"}},{"pos":"","cn":"","en":"an arm and a leg→see: ; with your tail between your legs→see: ;"}]},"media":{"uk":"media/uk/leg__gb_1.mp3","us":"media/us/leg__us_1.mp3","img":["media/ldoce/img/antique_chair.jpg"]},"examples":[{"en":"We saw the police coming and legged it down the road.","cn":"我们看见警察来了就顺着马路逃跑了。"},{"en":"Without written evidence, we don't have a leg to stand on.","cn":"我们没有书面证据就站不住脚。"}]},"legs":{"oxford":{"phon":"leɡ","pos":"noun","senses":[{"en":"one of the long parts that connect the feet to the rest of the body","cn":"腿"},{"en":"the leg of an animal, especially the top part, cooked and eaten （","cn":"尤指供食用的）动物的腿，腿肉"}]}},"leave":{"media":{"uk":"media/uk/leave__gb_1.mp3","us":"media/us/leave__us_1.mp3"},"oxford":{"phon":"liːv","pos":"verb","senses":[{"en":"to go away from a person or a place","cn":"离开（某人或某处）","g":"[intransitive, transitive]","sc":"place/person","ex":{"en":"Come on, it's time we left (= time for us to leave).","cn":"快点，我们该走了。"}},{"en":"to stop living at a place, belonging to a group, working for an employer, etc.","cn":"离开居住地点（或群体、工作单位等）","g":"[intransitive, transitive]","lab":"British English","sc":"home/job/school","ex":{"en":"My assistant is threatening to leave.","cn":"我的助理以辞职相要挟。"}},{"en":"to leave your wife, husband or partner permanently","cn":"遗弃；丢弃","g":"[intransitive, transitive]","sc":"partner","ex":{"en":"I was afraid you'd leave if you knew the truth.","cn":"我怕你知道真相就会离开。"}},{"en":"to go away from a place without taking something/somebody with you","cn":"忘了带；丢下","g":"[transitive]","sc":"somebody/something in place/condition","ex":{"en":"I'll have to go back—I've left my jacket.","cn":"我得回去一下。我把夹克忘了。"}},{"en":"to make or allow somebody/something to remain in a particular condition, place, etc.","cn":"使保留，让…处于（某种状态、某地等）","g":"[transitive]","sc":"somebody/something in place/condition","ex":{"en":"Leave the door open, please.","cn":"请把门开着吧。"}},{"en":"to remain to be used, sold, etc.","cn":"留下备用（或销售等）","g":"[transitive]","sc":"somebody/something in place/condition","ex":{"en":"Is there any coffee left?","cn":"还有咖啡剩下吗？"}},{"en":"to make something happen or remain as a result","cn":"使发生；造成，使留下为（某种结果）","g":"[transitive]","sc":"somebody/something in place/condition","ex":{"en":"Red wine leaves a stain.","cn":"红葡萄酒会留下污渍。"}},{"en":"to deliver, write or record something to be seen or heard later","cn":"发布；记下；写下；留下","g":"[transitive]","sc":"deliver","ex":{"en":"Lots of people had left comments under the post.","cn":"很多人在帖子下面留了言。"}},{"en":"to not do something or deal with something immediately","cn":"不立刻做；不马上处理","g":"[transitive]","sc":"something to do later","ex":{"en":"Leave the dishes—I'll do them later.","cn":"盘子先搁着吧，我等会儿再洗。"}},{"en":"to allow somebody to take care of something","cn":"把…留交；交托；委托","g":"[transitive]","sc":"responsibility to somebody","ex":{"en":"You can leave the cooking to me.","cn":"你可以把做饭的事交给我。"}},{"en":"to give something to somebody when you die","cn":"（去世时）遗赠，遗留","g":"[transitive]","sc":"after death","ex":{"en":"He left a large estate.","cn":"他留下了一大笔遗产。"}},{"en":"to have family who continue to live after your death","cn":"（死后）留下（家人）","g":"[transitive]","sc":"after death","ex":{"en":"He leaves a wife and two children.","cn":"他遗下妻子和两个孩子。"}},{"en":"to have a particular amount left over","cn":"剩余；余下","g":"[transitive]","sc":"mathematics","ex":{"en":"Seven from ten leaves three.","cn":"10 减 7 得 3。"}},{"en":"a period of time when you are allowed to be away from work for a holiday or for a special reason","cn":"假期；休假","ex":{"en":"to take a month’s paid/unpaid leave","cn":"带薪／不带薪休假一个月"},"pos":"noun"},{"en":"official permission to do something","cn":"准许；许可","lab":"formal","ex":{"en":"to be absent without leave","cn":"未经许可擅自离开"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"离开（某处或某人）","en":"If you leave a place or person, you go away from that place or person.","ex":{"en":"He would not be allowed to leave the country","cn":"他可能会被禁止离开该国。"}},{"pos":"VERB 动词","cn":"脱离；退出；辞去","en":"If you leave an institution, group, or job, you permanently stop attending that institution, being a member of that group, or doing that job.","ex":{"en":"He left school with no qualifications","cn":"他没有获得任何学历证书便离开了学校。"}},{"pos":"VERB 动词","cn":"抛下，离弃（配偶）；离开（关系亲密的人）","en":"If you leave your husband, wife, or some other person with whom you have had a close relationship, you stop living with them or you finish the relationship.","ex":{"en":"He'll never leave you. You need have no worry","cn":"他不会离开你的，你不用担心。"}},{"pos":"VERB 动词","cn":"放下；丢下；把…交给","en":"If you leave something or someone in a particular place, you let them remain there when you go away. If you leave something or someone with a person, you let them remain with that person so they are safe while you are away.","ex":{"en":"I left my bags in the car","cn":"我把包放在车里了。"}},{"pos":"VERB 动词","cn":"留（信息、口信）","en":"If you leave a message or an answer, you write it, record it, or give it to someone so that it can be found or passed on.","ex":{"en":"You can leave a message on our answering machine","cn":"您可以在我们的答录机上留言。"}},{"pos":"VERB 动词","cn":"剩下，留下（某人做某事）","en":"If you leave someone doing something, they are doing that thing when you go away from them.","ex":{"en":"Salter drove off, leaving Callendar surveying the scene.","cn":"索尔特开车走了，剩下卡伦德勘查现场。"}},{"pos":"VERB 动词","cn":"听任（某人做某事）；听（某人）自便","en":"If you leave someone to do something, you go away from them so that they do it on their own. If you leave someone to himself or herself, you go away from them and allow them to be alone.","ex":{"en":"I'd better leave you to get on with it, then","cn":"那我还是让你一个人接着干吧。"}},{"pos":"VERB 动词","cn":"留出（一定的量）备用","en":"To leave an amount of something means to keep it available after the rest has been used or taken away.","ex":{"en":"He always left a little food for the next day","cn":"他总是留下一点儿食物第二天吃。"}},{"pos":"VERB 动词","cn":"（数目相减后）剩余，余下","en":"If you take one number away from another, you can say that it leaves the number that remains. For example, five take away two leaves three."},{"pos":"VERB 动词","cn":"（尤指把令人不快或困难的事）留给，扔给（某人）","en":"To leave someone with something, especially when that thing is unpleasant or difficult to deal with, means to make them have it or make them responsible for it.","ex":{"en":"...a crash which left him with a broken collarbone","cn":"造成他锁骨骨折的车祸"}},{"pos":"VERB 动词","cn":"招致；造成","en":"If an event leaves people or things in a particular state, they are in that state when the event has finished.","ex":{"en":"...violent disturbances which have left at least ten people dead","cn":"造成至少10人死亡的暴乱"}},{"pos":"VERB 动词","cn":"（常指因不喜欢而）不碰（食物或饮料）","en":"If you leave food or drink, you do not eat or drink it, often because you do not like it.","ex":{"en":"If you don't like the cocktail you ordered, just leave it and try a different one.","cn":"你要是不喜欢你要的鸡尾酒，就别喝了，要点别的吧。"}},{"pos":"VERB 动词","cn":"留下（痕迹、影响等）","en":"If something leaves a mark, effect, or sign, it causes that mark, effect, or sign to remain as a result.","ex":{"en":"A muscle tear will leave a scar after healing","cn":"肌肉撕裂复原后会留下疤痕。"}},{"pos":"VERB 动词","cn":"使处于（某个状态或位置）","en":"If you leave something in a particular state, position, or condition, you let it remain in that state, position, or condition.","ex":{"en":"He left the album open on the table","cn":"他把相册摊在桌上没收。"}},{"pos":"VERB 动词","cn":"（有意）留出（空间）","en":"If you leave a space or gap in something, you deliberately make that space or gap.","ex":{"en":"Leave a gap at the top and bottom so air can circulate.","cn":"上下各留一个口子通风。"}},{"pos":"VERB 动词","cn":"把（工作）交托；把（决定或选择权）留交","en":"If you leave a job, decision, or choice to someone, you give them the responsibility for dealing with it or making it.","ex":{"en":"Affix the blue airmail label and leave the rest to us","cn":"贴上蓝色的空邮标签，其余的事情交给我们。"}},{"pos":"VERB 动词","cn":"（安排、协议等很大程度上）视乎，取决于","en":"If you say that something such as an arrangement or an agreement leaves a lot to another thing or person, you are critical of it because it is not adequate and its success depends on the other thing or person.","ex":{"en":"The ceasefire leaves a lot to the goodwill of the forces involved","cn":"停火协议的执行很大程度取决于各方武装力量的意愿。"}},{"pos":"VERB 动词","cn":"限制（某人于某一行动或机会）","en":"To leave someone with a particular course of action or the opportunity to do something means to let it be available to them, while restricting them in other ways.","ex":{"en":"This left me only one possible course of action","cn":"这样我只有一条路可走。"}},{"pos":"VERB 动词","cn":"搁延（至某一时刻）","en":"If you leave something until a particular time, you delay doing it or dealing with it until then.","ex":{"en":"Don't leave it all until the last minute.","cn":"不要把什么都拖到最后一分钟。"}},{"pos":"VERB 动词","cn":"搁下，转换（话题）","en":"If you leave a particular subject, you stop talking about it and start discussing something else.","ex":{"en":"I think we'd better leave the subject of Nationalism","cn":"我看我们最好还是搁下民族主义这个话题吧。"}},{"pos":"VERB 动词","cn":"（死后）遗留","en":"If you leave property or money to someone, you arrange for it to be given to them after you have died.","ex":{"en":"He died two and a half years later, leaving everything to his wife.","cn":"他于两年半后去世，把所有遗产都留给了妻子。"}},{"pos":"VERB 动词","cn":"（身后）留下（配偶或孩子）","en":"If you say that someone leaves a wife, husband, or a particular number of children, you mean that the wife, husband, or children remain alive after that person has died.","ex":{"en":"It is for his humanity as much as his music that his numerous friends and pupils will remember him. He leaves a wife, son and daughter.","cn":"他的仁爱精神，以及他的音乐，都将长留在无数友人和学生的记忆里。他身后遗下妻子和一对儿女。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"假期；休假","en":"Leave is a period of time when you are not working at your job, because you are on holiday or vacation, or for some other reason. If you are on leave, you are not working at your job.","ex":{"en":"Why don't you take a few days' leave?","cn":"你为什么不休几天假？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"准许；许可","en":"If you ask for leave to do something, you ask for permission to do it.","ex":{"en":"...an application for leave to appeal against the judge's order.","cn":"不服法官指令的上诉申请"}},{"pos":"PHRASE 短语","cn":"听…自便；随…去；不打扰","en":"If you leave someone or something alone, or if you leave them be, you do not pay them any attention or bother them.","ex":{"en":"Some people need to confront a traumatic past; others find it better to leave it alone","cn":"有人需要直面过去的创伤，有人则觉得不去想它为妙。"}},{"pos":"PREP-PHRASE 短语介词","cn":"姑莫论；搁置一旁","en":"You use leaving aside or leaving to one side when mentioning a fact or detail that you want to ignore when making a general statement.","ex":{"en":"Leaving aside the question of privacy, constant surveillance can be remarkably convenient.","cn":"如果不去管隐私问题的话，实施不间断监视其实是非常便利的。"}},{"pos":"PHRASE 短语","cn":"告别；辞别","en":"When you take your leave or take leave of someone, you say goodbye and go.","ex":{"en":"He thanked them for the pleasure of their company and took his leave.","cn":"他感谢他们的愉快陪伴，然后道别走了。"}},{"pos":"PHRASE 短语","cn":"不要弄巧成拙；不要没事找事","en":"If someone tells you to leave well alone, they are telling you not to interfere in something, because it is all right as it is and you might only make it worse.","ex":{"en":"He knew when to leave well alone and when to interfere.","cn":"他知道什么时候该适可而止，什么时候该插手干预。"}},{"pos":"PHRASE短语","cn":"（从…）中断之处，停止之处","en":"If something continues from where it left off, it starts happening again at the point where it had previously stopped.","ex":{"en":"As soon as the police disappear the violence will take up from where it left off.","cn":"警察一走，暴力事件就会死灰复燃。"}},{"pos":"","cn":"","en":"to leave a lot to be desired→see: ; to leave someone to their own devices→see: ; to take leave of your senses→see: ; take it or leave it→see: ;"},{"pos":"","cn":"","en":"相关词组：leave behind leave off leave out"}]},"examples":[{"en":"She left out an ‘m’ in ‘accommodation’.","cn":"她在 accommodation 一词中漏掉了一个字母 m。"},{"en":"‘Where shall we eat?’ ‘I'll leave it entirely (up) to you (= you can decide). ’ “","cn":"我们上哪儿吃去？” “我全交给你来决定好了。”"}]},"legitimate":{"media":{"uk":"media/uk/legitimate__gb_1.mp3","us":"media/us/legitimate__us_1.mp3"},"oxford":{"phon":"lɪˈdʒɪtɪmət","pos":"adjective","senses":[{"en":"for which there is a fair and acceptable reason","cn":"正当合理的；合情合理的","ex":{"en":"a legitimate grievance","cn":"正当的投诉"}},{"en":"allowed and acceptable according to the law","cn":"合法的；法律认可的；法定的","ex":{"en":"the legitimate government of the country","cn":"这个国家的合法政府"}},{"en":"born when its parents are legally married to each other","cn":"合法婚姻所生的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合法的；依法的；法律认可的","en":"Something that is legitimate is acceptable according to the law.","ex":{"en":"The French government has condemned the coup in Haiti and has demanded the restoration of the legitimate government","cn":"法国政府对海地政变表示谴责，并要求恢复合法政府的地位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合情理的；有道理的；正当的","en":"If you say that something such as a feeling or claim is legitimate, you think that it is reasonable and justified.","ex":{"en":"That's a perfectly legitimate fear","cn":"怀有这种恐惧完全在情理之中。"}},{"pos":"ADJ 形容词","cn":"婚生的","en":"A legitimate child is one whose parents were married before he or she was born.","ex":{"en":"We only married in order that the child should be legitimate.","cn":"我们结婚纯粹是为了给孩子一个合法身份。"}},{"pos":"VERB 动词","cn":"同legitimize","en":"To legitimate something means the same as to legitimize it.","ex":{"en":"We want to legitimate this process by passing a law.","cn":"我们希望通过立法来使这一程序合法化。"}}]},"examples":[{"en":"She can now legitimately claim to be the best in the world.","cn":"现在她可以理所当然地声称自己是世界上最优秀的。"},{"en":"I intend to challenge the legitimacy of his claim.","cn":"我打算对他的声明是否正确提出质疑。"}]},"lee":{"media":{"uk":"media/uk/lee__gb_1.mp3","us":"media/us/lee__us_1.mp3"},"oxford":{"phon":"liː","pos":"noun","senses":[{"en":"the side or part of something that provides shelter from the wind","cn":"背风处；避风处","g":"[singular]","ex":{"en":"We built the house in the lee of the hill.","cn":"我们把房子盖在山的背风面。"}},{"en":"the substance that is left at the bottom of a bottle of wine, a container of beer, etc.","cn":"（酒瓶等容器中的）沉淀物，残渣","g":"[plural]"},{"en":"a first name for boys or girls","cn":"李（男子或女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"庇护所；背风处","en":"The lee of a place is the shelter that it gives from the wind or bad weather.","ex":{"en":"...the cathedral, which nestles in the lee of a hill beneath the town","cn":"坐落于小镇下面一座小山背风处的大教堂"}},{"pos":"ADJ 形容词","cn":"（船）背风（面）的，下风的","en":"In sailing, the lee side of a ship is the one that is away from the wind."},{"pos":"N-PLURAL 复数名词","cn":"（酒瓶或酒桶底部的）渣滓，沉淀物","en":"The lees are the substance that collects at the bottom of a bottle or barrel of wine.","ex":{"en":"...a glass-fronted barrel showing the wine resting on its lees.","cn":"可以看到沉有渣滓的葡萄酒的玻璃面酒桶"}}]},"examples":[{"en":"We sat in the lee of a tall hedge.","cn":"我们坐在高树篱背风的一侧。"}]},"leaf":{"oxford":{"phon":"liːf","pos":"noun","senses":[{"en":"a flat green part of a plant, growing from a stem or branch or from the root","cn":"叶；叶片；叶子","g":"[countable]","ex":{"en":"lettuce/cabbage/oak leaves","cn":"莴苣叶；卷心菜叶；橡树叶"}},{"en":"having leaves of the type or number mentioned","cn":"有…状叶的；有…片叶的","ex":{"en":"a four-leaf clover","cn":"四叶车轴草"}},{"en":"a sheet of paper, especially a page in a book","cn":"（纸）页，张；（尤指书的）页","g":"[countable]","ex":{"en":"She carefully turned the leaves of the precious volume.","cn":"她小心翼翼地翻动这本珍贵书籍的书页。"}},{"en":"metal, especially gold or silver, in the form of very thin sheets","cn":"薄金属片；（尤指金或银）箔","g":"[uncountable]","ex":{"en":"gold leaf","cn":"金箔"}},{"en":"a part of a table that can be lifted up, or an extra section that can be added into the table, in order to make the table bigger","cn":"活动桌板；折叠桌板","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树叶；叶子","en":"The leaves of a tree or plant are the parts that are flat, thin, and usually green. Many trees and plants lose their leaves in the winter and grow new leaves in the spring.","ex":{"en":"In the garden, the leaves of the horse chestnut had already fallen","cn":"花园里，七叶树已经落叶了。"}},{"pos":"N-COUNT 可数名词","cn":"（书）页","en":"A leaf is one of the pieces of paper of which a book is made.","ex":{"en":"He flattened the wrappers and put them between the leaves of his book.","cn":"他把包装纸压平，夹在书里。"}},{"pos":"PHRASE 短语","cn":"师法；效法；以（某人）为榜样","en":"If you take a leaf from someone's book you behave in the same way as them because you want to be like that person or as successful as they are.","ex":{"en":"Maybe we should take a leaf out of Branson's book. It's easy to see how he became a billionaire","cn":"也许我们应该效法布兰森。我们都不难看出他是怎样成为亿万富翁的。"}},{"pos":"PHRASE 短语","cn":"重新开始；洗心革面；改过自新","en":"If you say that you are going to turn over a new leaf, you mean that you are going to start to behave in a better or more acceptable way.","ex":{"en":"He realized he was in the wrong and promised to turn over a new leaf.","cn":"他认识到自己错了，答应改过自新。"}},{"pos":"PHRASE 短语","cn":"（因寒冷、恐惧等）浑身发抖，抖如落叶","en":"If you say that someone is shaking like a leaf, you mean that their body is shaking a lot, for instance because they are very cold or frightened.","ex":{"en":"I didn't think about the danger at the time. Afterwards I was shaking like a leaf.","cn":"我那时候没想到有危险，事后我吓得直发抖。"}},{"pos":"","cn":"","en":"相关词组：leaf through"}]},"media":{"uk":"media/uk/leaf__gb_1.mp3","us":"media/us/leaf__us_1.mp3"},"examples":[{"en":"The trees are just coming into leaf.","cn":"树木正好在长叶子。"},{"en":"the dead leaves of autumn/the fall","cn":"秋天的枯叶"}]},"letters":{"oxford":{"phon":"ˈletə(r)","pos":"noun","senses":[{"en":"a message that is written down or printed on paper and usually put in an envelope and sent to sb","cn":"信；函"},{"en":"a written or printed sign representing a sound used in speech","cn":"字母"}]},"media":{"uk":"media/uk/letter__gb_1.mp3","us":"media/us/letter__us_1.mp3"}},"legislator":{"media":{"uk":"media/uk/legislator__gb_1.mp3","us":"media/us/legislator__us_1.mp3"},"oxford":{"phon":"ˈledʒɪsleɪtə(r)","pos":"noun","senses":[{"en":"a member of a group of people that has the power to make laws","cn":"立法委员","ex":{"en":"Seven of the state’s 90 legislators have been indicted.","cn":"90位州立法委员中有7位遭起诉。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"立法者；立法机关成员；议会议员","en":"A legislator is a person who is involved in making or passing laws.","ex":{"en":"...an attempt to get US legislators to change the system.","cn":"旨在推动美国的立法者进行制度变革的努力"}}]}},"lecturers":{"oxford":{"phon":"ˈlektʃərə(r)","pos":"noun","senses":[{"en":"a person who gives a lecture","cn":"讲课者；讲授者；讲演者"},{"en":"(especially in Britain) a person who teaches at a university or college （","cn":"尤指英国大学的）讲师"}]}},"lecturer":{"oxford":{"phon":"ˈlektʃərə(r)","pos":"noun","senses":[{"en":"a person who gives a lecture","cn":"讲课者；讲授者；演讲者","ex":{"en":"She's a superb lecturer.","cn":"她是一个出色的演讲者。"}},{"en":"(especially in the UK) a person who teaches at a university or college","cn":"（尤指英国大学的）讲师","ex":{"en":"He's a lecturer in French at Oxford.","cn":"他是牛津大学的法语讲师。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（大学或学院的）讲师","en":"A lecturer is a teacher at a university or college.","ex":{"en":"...a lecturer in law at Southampton University.","cn":"南安普敦大学的一位法学讲师"}}]},"media":{"uk":"media/uk/lecturer__gb_1.mp3","us":"media/us/lecturer__us_1.mp3"},"examples":[{"en":"He's a lecturer in French at Oxford.","cn":"他是牛津大学的法语讲师。"},{"en":"She's a superb lecturer.","cn":"她是一个出色的演讲者。"}]},"leader":{"media":{"uk":"media/uk/leader__gb_1.mp3","us":"media/us/leader__us_1.mp3"},"oxford":{"phon":"ˈliːdə(r)","pos":"noun","senses":[{"en":"a person who leads a group of people, especially the head of a country, an organization, etc.","cn":"领导者；领袖；首领","ex":{"en":"party/world leaders","cn":"政党／世界领导人"}},{"en":"a person or thing that is the best, or in first place in a race, business, etc.","cn":"最佳的人（或物）；（在赛跑、商业等活动中）处于领先地位的人（或物）","ex":{"en":"She was among the leaders of the race from the start.","cn":"比赛一开始她就与领先的几位选手并驾齐驱。"}},{"en":"the most important violin player in an orchestra","cn":"（管弦乐队的）首席小提琴手","lab":"British English"},{"en":"an important article in a newspaper that expresses the editor's opinion about an item of news or an issue; in the US also a comment on radio or television that expresses the opinion of the station or network","cn":"（报章的）社论；（美国电台或电视台的）评论","lab":"both British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"领袖；领导者","en":"The leader of a group of people or an organization is the person who is in control of it or in charge of it.","ex":{"en":"We now need a new leader of the party and a new style of leadership","cn":"我们现在需要一位新的政党领袖和一种新的领导作风。"}},{"pos":"N-COUNT 可数名词","cn":"（比赛或竞赛中的）领先者，占先者","en":"The leader at a particular point in a race or competition is the person who is winning at that point.","ex":{"en":"The leaders came in two minutes clear of the field","cn":"优胜者较其他参赛者快两分钟。"}},{"pos":"N-COUNT 可数名词","cn":"（产品或公司中的）首屈一指者，佼佼者","en":"The leader among a range of products or companies is the one that is most successful.","ex":{"en":"Procter & Gamble is the leader in the mass market cosmetics industry.","cn":"宝洁是大众化妆品行业中的领头羊。"}},{"pos":"N-COUNT 可数名词","cn":"（交响乐团的）首席小提琴手","en":"The leader of an orchestra is the most senior violin player, who acts as a deputy to the conductor."},{"pos":"N-COUNT 可数名词","cn":"（交响乐团的）指挥","en":"The leader of an orchestra is the conductor."},{"pos":"N-COUNT 可数名词","cn":"（报纸上的）社评，社论","en":"A leader in a newspaper is a piece of writing which gives the editor's opinion on an important news item."},{"pos":"N-COUNT 可数名词","cn":"（报纸的）要闻，头条","en":"A leader in a newspaper is the most important story in it."}]},"examples":[{"en":"She was among the leaders of the race from the start.","cn":"比赛一开始她就与领先的几位选手并驾齐驱。"},{"en":"The company is a world leader in electrical goods.","cn":"这家公司的电器产品在全世界首屈一指。"}]},"legally":{"oxford":{"phon":"ˈliːɡəli","pos":"adverb","senses":[{"en":"in a way that is connected with the law","cn":"法律上：以与法律相关的方式","ex":{"en":"a legally binding agreement","cn":"具有法律约束力的协议"}},{"en":"in a way that is allowed or required by law","cn":"法律上：法律允许或要求的方式","ex":{"en":"You are legally entitled to a full refund.","cn":"你依法有权得到全额退款。"}}]},"media":{"uk":"media/uk/legally__gb_1.mp3","us":"media/us/legally__us_1.mp3"},"examples":[{"en":"to be legally responsible for sb/sth","cn":"对某人/某事负有法律责任"},{"en":"a legally binding agreement","cn":"具有法律约束力的协议"}]},"lending":{"oxford":{"phon":"ˈlendɪŋ","pos":"noun","senses":[{"en":"the act of lending money","cn":"放款；贷放","ex":{"en":"Lending by banks rose to $10 billion last year.","cn":"去年银行发放的贷款增至 100 亿美元。"}}]},"media":{"uk":"media/uk/lending__gb_1.mp3","us":"media/us/lending__us_1.mp3"},"examples":[{"en":"Lending by banks rose to $10 billion last year.","cn":"去年银行发放的贷款增至 100 亿元。"}]},"lean":{"media":{"uk":"media/uk/lean__gb_1.mp3","us":"media/us/lean__us_1.mp3"},"oxford":{"phon":"liːn","pos":"verb","senses":[{"en":"to bend or move from a straight position to a sloping position","cn":"前俯（或后仰）；倾斜","g":"[intransitive]","ex":{"en":"I leaned back in my chair.","cn":"我仰靠在椅背上。"}},{"en":"to rest on or against something for support","cn":"倚靠；靠在；靠置","g":"[intransitive]","ex":{"en":"A shovel was leaning against the wall.","cn":"一把铁铲靠墙放着。"}},{"en":"to make something rest against something in a sloping position","cn":"使斜靠","g":"[transitive]","ex":{"en":"Can I lean my bike against the wall?","cn":"我能把自行车靠在这墙上吗？"}},{"en":"without much fat; thin and fit","cn":"脂肪少的；瘦而结实的","lab":"usually approving","ex":{"en":"He had a lean, muscular body.","cn":"他体格精瘦结实。"},"pos":"adjective"},{"en":"containing little or no fat","cn":"瘦的","ex":{"en":"a lean, tender piece of beef","cn":"一块又瘦又嫩的牛肉"},"pos":"adjective"},{"en":"difficult and not producing much money, food, etc.","cn":"难以赚钱的；生产不出（食物等）的；贫乏的","g":"[usually before noun]","ex":{"en":"a lean period/spell","cn":"不景气时期"},"pos":"adjective"},{"en":"strong and efficient because they avoid waste in their processes and do not have more employees than is necessary","cn":"精干的；精简的","ex":{"en":"The changes made the company leaner and more competitive.","cn":"改革使公司更精干，更有竞争力。"},"pos":"adjective"},{"en":"the part of meat that has little or no fat","cn":"瘦肉","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（身体）倾斜，倾侧","en":"When you lean in a particular direction, you bend your body in that direction.","ex":{"en":"Eileen leaned across and opened the passenger door","cn":"艾琳倾身把后座门打开。"}},{"pos":"VERB 动词","cn":"（使）倚；（使）靠","en":"If you lean on or against someone or something, you rest against them so that they partly support your weight. If you lean an object on or against something, you place the object so that it is partly supported by that thing.","ex":{"en":"She was feeling tired and was glad to lean against him","cn":"她正感到有些疲倦，因此很高兴可以靠在他身上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（壮健而）清瘦的","en":"If you describe someone as lean, you mean that they are thin but look strong and healthy.","ex":{"en":"Like most athletes, she was lean and muscular","cn":"跟大部分运动员一样，她身形清瘦，肌肉结实。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（肉）瘦的","en":"If meat is lean, it does not have very much fat.","ex":{"en":"It is a beautiful meat, very lean and tender.","cn":"这块肉很好，又瘦又嫩。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（组织）精简的，精干的","en":"If you describe an organization as lean, you mean that it has become more efficient and less wasteful by getting rid of staff, or by dropping projects which were unprofitable.","ex":{"en":"The value of the pound will force British companies to be leaner and fitter.","cn":"英镑目前的汇率将迫使英国公司厉行精兵简政。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"萧条的；不景气的","en":"If you describe periods of time as lean, you mean that people have less of something such as money or are less successful than they used to be.","ex":{"en":"...the lean years of the 1930s","cn":"萧条的20世纪30年代"}},{"pos":"","cn":"","en":"相关词组：lean on lean towards"}]},"examples":[{"en":"The company recovered well after going through several lean years.","cn":"经历了几年的萧条后，这家公司的业务才完全恢复了正常。"},{"en":"The government has been leaning on the TV company not to broadcast the show.","cn":"政府一直给电视公司施加压力，不准播放此节目。"}]},"leisure":{"media":{"uk":"media/uk/leisure__gb_1.mp3","us":"media/us/leisure__us_1.mp3"},"oxford":{"phon":"ˈleʒə(r)","pos":"noun","senses":[{"en":"time when you are not working or studying; free time","cn":"闲暇；空闲；休闲","ex":{"en":"These days we have more money and more leisure to enjoy it.","cn":"如今我们钱多了，也有更多时间来花钱享受了。"}},{"en":"activities that you enjoy in your free time","cn":"休闲活动；业余爱好","ex":{"en":"These days we have increased opportunities for leisure.","cn":"这些天我们有更多的休闲活动机会。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"闲暇；空余；休闲时间","en":"Leisure is the time when you are not working and you can relax and do things that you enjoy.","ex":{"en":"...a relaxing way to fill my leisure time.","cn":"我打发空余时间的轻松办法"}},{"pos":"PHRASE 短语","cn":"从容不迫；不慌不忙；慢悠悠","en":"If someone does something at leisure or at their leisure, they enjoy themselves by doing it when they want to, without hurrying.","ex":{"en":"You will be able to stroll at leisure through the gardens","cn":"您可在花园里闲逛。"}}]},"examples":[{"en":"These days we have more money and more leisure to enjoy it.","cn":"如今我们钱多了，也有更多时间来花钱享受了。"},{"en":"I suggest you take the forms away and read them at your leisure.","cn":"我建议你把表格带回去有空慢慢看。"}]},"legalization":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the law so that something becomes legal","cn":""},{"en":"to make an illegal activity no longer a crime, so that the people who do it can no longer be punished by law","cn":""}]},"examples":[{"en":"Abortion was legalized in the 1960s.","cn":"","src":"ld"}],"media":{"uk":"media/uk/legalization__gb_1.mp3","us":"media/us/legalization__us_1.mp3"},"oxford":{"phon":"ˌliːɡəlaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the fact of making something legal","cn":"合法（性）","ex":{"en":"They argue for the legalization of soft drugs.","cn":"他们主张软毒品合法化。"}}]}},"leaned":{"oxford":{"phon":"liːn","pos":"verb","senses":[{"en":"to bend or move from a vertical position","cn":"前俯；后仰；倾斜"},{"en":"to rest on or against sth for support","cn":"倚靠；靠在；靠置"}]}},"lenses":{"oxford":{"phon":"lenz","pos":"noun","senses":[{"en":"a curved piece of glass or plastic that makes things look larger, smaller or clearer when you look through it","cn":"透镜；镜片"},{"en":"( anatomy","cn":"解 ) the transparent part of the eye, behind the pupil , that focuses light so that you can see clearly （眼球的）晶状体"}]}},"lessons":{"oxford":{"phon":"ˈlesn","pos":"noun","senses":[{"en":"a period of time in which sb is taught sth","cn":"一节课；一课时"},{"en":"something that is intended to be learned","cn":"课；教学单元"}]}},"legislatures":{"oxford":{"phon":"ˈledʒɪsleɪtʃə(r)","pos":"noun","senses":[{"en":"a group of people who have the power to make and change laws","cn":"立法机关"}]}},"leaders":{"oxford":{"phon":"ˈliːdə(r)","pos":"noun","senses":[{"en":"a person who leads a group of people, especially the head of a country, an organization, etc.","cn":"领导者；领袖；首领"},{"en":"a person or thing that is the best, or in first place in a race, business, etc.","cn":"最佳的人（或物）；（在赛跑、商业等活动中）处于领先地位的人（或物）"}]}},"leads":{"oxford":{"phon":"liːd","pos":"verb","senses":[{"en":"to go with or in front of a person or an animal to show the way or to make them go in the right direction","cn":"带路；领路；引领"},{"en":"to connect one object or place to another （","cn":"与 … ）相连，相通"}]}},"leaped":{"oxford":{"phon":"liːp","pos":"verb","senses":[{"en":"to jump high or a long way","cn":"跳；跳跃；跳越"},{"en":"to move or do sth suddenly and quickly","cn":"猛冲；突然做（某事）"}]}},"leaving":{"oxford":{"phon":"liːv","pos":"verb","senses":[{"en":"to go away from a person or a place","cn":"离开（某人或某处）"},{"en":"to stop living at a place, belonging to a group, working for an employer, etc.","cn":"离开居住地点（或群体、工作单位等）"}]}},"legacies":{"oxford":{"phon":"ˈleɡəsi","pos":"noun","senses":[{"en":"money or property that is given to you by sb when they die","cn":"遗产；遗赠财物"},{"en":"a situation that exists now because of events, actions, etc. that took place in the past","cn":"遗留问题；后遗症"}]}},"lets":{"oxford":{"phon":"let","pos":"verb","senses":[{"en":"to allow sb to do sth or sth to happen without trying to stop it","cn":"允许；让"},{"en":"to give sb permission to do sth","cn":"准许；许可；同意"}]}},"legions":{"oxford":{"phon":"ˈliːdʒən","pos":"noun","senses":[{"en":"a large group of soldiers that forms part of an army, especially the one that existed in ancient Rome （","cn":"尤指古罗马的）军团"},{"en":"( formal ) a large number of people of one particular type","cn":"大量，大批（某类型的人）"}]}},"legends":{"oxford":{"phon":"ˈledʒənd","pos":"noun","senses":[{"en":"a story from ancient times about people and events, that may or may not be true; this type of story","cn":"传说；传奇故事"},{"en":"a very famous person, especially in a particular field, who is admired by other people （","cn":"尤指某领域中的）传奇人物"}]}},"levels":{"oxford":{"phon":"ˈlevl","pos":"noun","senses":[{"en":"the amount of sth that exists in a particular situation at a particular time （","cn":"某时某情况下存在的）数量，程度，浓度"},{"en":"a particular standard or quality","cn":"标准；水平；质量；品级"}]}},"lemons":{"oxford":{"phon":"ˈlemən","pos":"noun","senses":[{"en":"a yellow citrus fruit with a lot of sour juice. Slices of lemon and lemon juice are used in cooking and drinks.","cn":"柠檬"},{"en":"lemon juice or a drink made from lemon","cn":"柠檬汁；柠檬饮料"}]}},"lengths":{"oxford":{"phon":"leŋθ","pos":"noun","senses":[{"en":"the size or measurement of sth from one end to the other","cn":"长；长度"},{"en":"the amount of time that sth lasts （","cn":"持续）时间的长短"}]}},"learnt":{"oxford":{"phon":"lɜːn","pos":"verb","senses":[{"en":"to gain knowledge or skill by studying, from experience, from being taught, etc.","cn":"学；学习；学到；学会"},{"en":"to become aware of sth by hearing about it from sb else","cn":"听到；得知；获悉"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld44learnt.mp3","us":"media/ldoce/hwd/ame/c/ld44learnt.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"Learnt is a past tense and past participle of learn."}]}},"leaps":{"oxford":{"phon":"liːp","pos":"verb","senses":[{"en":"to jump high or a long way","cn":"跳；跳跃；跳越"},{"en":"to move or do sth suddenly and quickly","cn":"猛冲；突然做（某事）"}]}},"learners":{"oxford":{"phon":"ˈlɜːnə(r)","pos":"noun","senses":[{"en":"a person who is finding out about a subject or how to do sth","cn":"学习者"},{"en":"a person who is learning to drive a car","cn":"学习驾车者；学习驾驶员"}]}},"legible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（字迹）清晰可辨的，清楚易读的","en":"Legible writing is clear enough to read.","ex":{"en":"My handwriting isn't very legible.","cn":"我写的字不那么好认。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"written clearly enough for you to read","cn":""},{"en":"written or printed clearly enough for you to read 〔","cn":"字迹〕可以辨认的﹐清晰易读的"}]},"vocab":{"pos":"adj","senses":[{"en":"Legible describes readable print or handwriting. If someone tells you that your writing looks like \"chicken scratch,\" it might not be legible, except to other chickens."}]},"collocations":{"phrases":["VERBS be","ADV. clearly, easily Her handwriting was clearly legible. | perfectly | barely, scarcely","PREP. to The price must be legible to a purchaser."]},"media":{"uk":"media/ldoce/hwd/bre/5/legible0205.mp3","us":"media/ldoce/hwd/ame/d/legible.mp3"},"examples":[{"en":"The signature was still legible.","cn":"签名仍清晰可辨。"},{"en":"legible handwriting","cn":"清楚易读的笔迹"}],"oxford":{"phon":"ˈledʒəbl","pos":"adjective","senses":[{"en":"clear enough to read","cn":"清晰可读的；清楚的","ex":{"en":"legible handwriting","cn":"清楚易读的笔迹"}}]}},"lesbian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"女同性恋的","en":"Lesbian is used to describe homosexual women.","ex":{"en":"Many of her best friends were lesbian.","cn":"她最要好的朋友中有很多都是女同性恋者。"}},{"pos":"ADJ 形容词","cn":"有关女同性恋者的","en":"Lesbian is used to describe the relationships and activities of homosexual women, and the organizations or publications intended for them or created by them.","ex":{"en":"...a long-term lesbian relationship.","cn":"长期的女同性恋关系"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"sexually attracted to people of the same sex","cn":""},{"en":"a woman who is sexually attracted to other women","cn":"女同性恋者"},{"en":"sexually attracted to people of the same sex","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"A lesbian is a woman who is attracted to other women. Two married women are in a lesbian relationship."}]},"collocations":{"phrases":["ADJ. butch | femme, lipstick","VERB + LESBIAN come out as She came out as a lesbian in her teens.","LESBIAN + NOUN icon The singer has become a lesbian icon."]},"media":{"uk":"media/ldoce/hwd/bre/0/lesbian0205.mp3","us":"media/ldoce/hwd/ame/c/lesbian.mp3"},"examples":[{"en":"lesbians and gays","cn":"女同性恋者与男同性恋者"},{"en":"the lesbian and gay community","cn":"男女同性恋群体"}],"oxford":{"phon":"ˈlezbiən","pos":"adjective","senses":[{"en":"sexually attracted to other women; connected with lesbians","cn":"女同性恋的；女同性恋者的","ex":{"en":"the lesbian and gay community","cn":"男女同性恋群体"}},{"en":"a woman who is sexually attracted to other women","cn":"女同性恋者","ex":{"en":"lesbians and gays","cn":"女同性恋者与男同性恋者"},"pos":"noun"}]}},"leak":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"漏；渗漏；泄漏","en":"If a container leaks, there is a hole or crack in it which lets a substance such as liquid or gas escape. You can also say that a container leaks a substance such as liquid or gas.","ex":{"en":"The roof leaked","cn":"屋顶漏雨。"}},{"pos":"N-COUNT 可数名词","cn":"裂缝；漏隙；漏洞","en":"A leak is a crack, hole, or other gap that a substance such as a liquid or gas can pass through.","ex":{"en":"...a leak in the radiator","cn":"暖气片上的一条裂缝"}},{"pos":"V-ERG 及物/不及物动词","cn":"走漏；泄露；透露","en":"If a secret document or piece of information leaks or is leaked, someone lets the public know about it.","ex":{"en":"Last year, a civil servant was imprisoned for leaking a document to the press","cn":"去年，一名公务员因向报界泄露了一份文件而被判入狱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if liquid flows, it moves in a steady continuous stream","cn":""},{"en":"to flow – used when saying that something flows in a particular direction","cn":""},{"en":"to flow out of something","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"A leak involves the release of something. It can be a behind-someone’s-back leak of sensitive information, a leak from a milk carton, or a leak in the roof that lets rain water drip in."}]},"collocations":{"phrases":["VERB + LEAK have The boat had a small leak. | spring The pipe has sprung a leak. | plug, stop I managed to plug the leak.","PREP. ~ in a leak in the roof 2 when gas/liquid escapes","ADJ. major, serious | minor | slow | fuel, gas, oil, radiation, radioactive","VERB + LEAK cause The dismantling of a nuclear reprocessing plant caused a leak of radioactivity yesterday. | detect, discover, find, notice","LEAK + VERB happen, occur","PREP. ~ from Pollution inspectors were called to a leak from a chemical factory. | ~ of a leak of dangerous chemicals 3 giving away informat","ADJ. security","LEAK + VERB come from sth The leak could only have come from one source."]},"media":{"uk":"media/ldoce/hwd/bre/3/leak_n0205.mp3","us":"media/ldoce/hwd/ame/9/leak1.mp3"},"examples":[{"en":"a leak to the press about the government plans on tax","cn":"有关政府税收计划的消息于新闻界的泄露"},{"en":"Details of the plan soon leaked out.","cn":"计划的细节很快就泄露出去了。"}],"oxford":{"phon":"liːk","pos":"verb","senses":[{"en":"to allow liquid or gas to get in or out through a small hole","cn":"漏；渗漏；泄漏","g":"[intransitive, transitive]","ex":{"en":"a leaking pipe","cn":"渗漏的管道"}},{"en":"to get in or out through a small hole in something","cn":"渗入；漏出","g":"[intransitive]","ex":{"en":"Water had started to leak into the cellar.","cn":"水已开始渗入地下室。"}},{"en":"to give secret information to the public, for example by telling a newspaper","cn":"泄露，透露（秘密信息）；走漏","g":"[transitive]","ex":{"en":"The contents of the report were leaked to the press.","cn":"报告的内容泄露到新闻界了。"}},{"en":"a small hole that lets liquid or gas flow in or out of something by accident","cn":"漏洞；裂缝；缝隙","lab":"British English","ex":{"en":"a leak in the roof","cn":"屋顶的漏洞"},"pos":"noun"},{"en":"liquid or gas that escapes through a hole in something","cn":"泄漏出的液体（或气体）","ex":{"en":"If you have no idea where the gas leak is coming from, it is always best to turn the complete system off.","cn":"如果不清楚具体的煤气泄漏点，关闭整个系统总是最好的办法。"},"pos":"noun"},{"en":"a deliberate act of giving secret information to the newspapers, etc.","cn":"（秘密信息的）透露","ex":{"en":"There has been a leak to the press about the government plans on tax.","cn":"有关政府税收计划的消息已经向媒体泄露。"},"pos":"noun"},{"en":"an act of passing urine from the body","cn":"撒尿","lab":"slang","ex":{"en":"to have/take a leak","cn":"撒尿"},"pos":"noun"}]}},"lenient":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"仁慈的；宽大的；宽容的","en":"When someone in authority is lenient, they are not as strict or severe as expected.","ex":{"en":"He believes the government already is lenient with drug traffickers","cn":"他认为政府对毒贩已经很宽容了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an official punishment that is lenient is not severe","cn":""},{"en":"criticism or a punishment that is mild is not strict, especially in a way that is surprising","cn":""},{"en":"not strict in the way that you punish people or control their behaviour","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're not overly strict, and you show tolerance and mercy when someone does something wrong, you're being lenient ."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. extremely, very | quite, relatively | excessively, unduly The appeal judge agreed that the original sentence was unduly lenient.","PREP. with The police are sometimes more lenient with female offenders."]},"media":{"uk":"media/ldoce/hwd/bre/6/lenient0205.mp3","us":"media/ldoce/hwd/ame/8/lenient.mp3"},"examples":[{"en":"She appealed to the judge for leniency.","cn":"她向法官请求宽大处理。"},{"en":"The judge was far too lenient with him.","cn":"法官对他太宽容了。"}],"oxford":{"phon":"ˈliːniənt","pos":"adjective","senses":[{"en":"not as strict as expected when punishing somebody or when making sure that rules are obeyed","cn":"（惩罚或执法时）宽大的，宽容的，仁慈的","ex":{"en":"a lenient sentence/fine","cn":"从宽的判刑／罚款"}}]}},"leukaemia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"白血病","en":"Leukaemia is a disease of the blood in which the body produces too many white blood cells."}]},"collocations":{"phrases":["ADJ. childhood","VERB + LEUKAEMIA have, suffer from | contract, develop | diagnose | treat sb for","LEUKAEMIA + NOUN case, patient, sufferer, victim | research | cluster The newspapers are full of stories of leukaemia clusters near nuclear "]},"oxford":{"phon":"luːˈkiːmiə","pos":"noun","senses":[{"en":"a serious disease in which too many white blood cells are produced, causing weakness and sometimes death","cn":"白血病","ex":{"en":"The newspapers are full of stories of leukaemia clusters near nuclear establishments.","cn":"报章满是在核设施附近发现白血病患者群的报道。"}}]}},"lever":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（操作机械的）杆，柄，把手","en":"A lever is a handle or bar that is attached to a piece of machinery and which you push or pull in order to operate the machinery.","ex":{"en":"Push the tiny lever on the lock","cn":"按一下锁上的小柄。"}},{"pos":"N-COUNT 可数名词","cn":"杠杆；撬棒","en":"A lever is a long bar, one end of which is placed under a heavy object so that when you press down on the other end you can move the object."},{"pos":"VERB 动词","cn":"撬动；撬起；用力移动","en":"If you lever something in a particular direction, you move it there, especially by using a lot of effort.","ex":{"en":"Neighbours eventually levered open the door with a crowbar","cn":"邻居们最终用一根铁撬把门撬开了。"}},{"pos":"N-COUNT 可数名词","cn":"（用作施加压力等的）手段，方法","en":"A lever is an idea or action that you can use to make people do what you want them to do, rather than what they want to do.","ex":{"en":"Radical, militant factions want to continue using the hostages as a lever to gain concessions from the west.","cn":"激进的好战派想要继续利用人质作筹码来换取西方的让步。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stick or handle on a machine or piece of equipment, that you move to operate it 〔","cn":"机器或设备的〕控制杆﹐操纵杆"},{"en":"a long thin piece of metal that you use to lift something heavy by putting one end under the object and pushing the other end down","cn":"杠杆"},{"en":"something you use to influence a situation to get the result that you want 〔","cn":"影响局势的〕方法﹐手段"}]},"vocab":{"pos":"n v","senses":[{"en":"A lever is a handle, sticking out at an angle, that allows you to operate a machine or close a door . When you pull the lever of a voting booth, you both cast your ballot and open the curtain."}]},"collocations":{"phrases":["ADJ. brake, control, gear","VERB + LEVER move, operate, position, press, pull, push, put, release, set, throw When the lever is operated, the machine sews backwards. To","PREP. by (means of) a ~ Th e machine is operated by means of a lever .","PHRASES the position of the lever 2 means of achieving sth","ADJ. powerful, useful","VERB + LEVER act as, be, give sb, provide (sb with), serve as | use sth as","PREP. ~ against If this allegation i s true, it will give us a useful leve r against him. | ~ for This coul d serve as a powerful lever for "]},"media":{"uk":"media/ldoce/hwd/bre/3/lever_n0205.mp3","us":"media/ldoce/hwd/ame/1/lever1.mp3"},"examples":[{"en":"The threat of sanctions is our most powerful lever for peace.","cn":"实施制裁的威胁是我们争取和平最有力的施压手段。"},{"en":"Pull the lever towards you to adjust the speed.","cn":"把操纵杆往你身前拉动以调节速度。"}],"oxford":{"phon":"ˈliːvə(r)","pos":"noun","senses":[{"en":"a handle used to operate a vehicle or a machine","cn":"（车辆或机器的）操纵杆，控制杆","ex":{"en":"Pull the lever towards you to adjust the speed.","cn":"把操纵杆往你身前拉动以调节速度。"}},{"en":"a long piece of wood, metal, etc. used for lifting or opening something by somebody placing one end of it under an object and pushing down on the other end","cn":"杠杆","ex":{"en":"We had to use a lever to prise open the window.","cn":"我们不得不用杠杆撬开窗户。"}},{"en":"an action that is used to put pressure on somebody to do something they do not want to do","cn":"施压的行为","ex":{"en":"The threat of sanctions is our most powerful lever for peace.","cn":"实施制裁的威胁是我们争取和平最有力的施压手段。"}},{"en":"to move something with a lever","cn":"（用杠杆）撬动","ex":{"en":"I levered the lid off the pot with a knife.","cn":"我用刀撬掉了罐盖。"},"pos":"verb"}]}},"lethargy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"慵懒；倦怠；没精打采","en":"Lethargy is the condition or state of being lethargic.","ex":{"en":"Symptoms include tiredness, paleness, and lethargy.","cn":"症状包括疲倦、脸色苍白、没有精神。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of being very tired","cn":""},{"en":"the feeling of wanting to sleep that you sometimes get when you are in a warm place or when you have drunk alcohol or taken medicine","cn":""},{"en":"a feeling of being very tired and weak - used especially in medical contexts","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Is your pet slug always this comatose, or is this display of lethargy unusual? The word lethargy describes inactivity or a lack of energy."}]},"collocations":{"phrases":["VERB + LETHARGY be overcome by, feel, suffer from She was suddenly overcome by lethargy. | sink into | drag/stir yourself out of, overcome, ","LETHARGY + VERB creep over/through sb, overtake sb After the meal, I could feel lethargy overtaking me.","PHRASES a feeling of lethargy trying to shake off the feeling of lethargy"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41lethargy.mp3","us":"media/ldoce/hwd/ame/f/ld41lethargy.mp3"},"examples":[{"en":"The weather made her lethargic.","cn":"那天气使得她无精打采。"},{"en":"New mothers often complain of lethargy and mild depression.","cn":"初为人母者经常抱怨说身体疲倦乏力﹐有轻微的抑郁。"}],"oxford":{"phon":"ˈleθədʒi","pos":"noun","senses":[{"en":"the state of not having any energy or enthusiasm for doing things","cn":"无精打采；没有热情；冷漠","ex":{"en":"The report criticizes the lethargy shown by employers when it comes to job creation.","cn":"该报告批评了雇主在创造就业机会方面表现出的冷漠态度。"}}]}},"leverage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（能够操控形势的）影响力，手段，优势","en":"Leverage is the ability to influence situations or people so that you can control what happens.","ex":{"en":"His function as a Mayor affords him the leverage to get things done through attending committee meetings.","cn":"他的市长身份使他有能力通过出席委员会会议来达成一些事情。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"杠杆力；杠杆作用","en":"Leverage is the force that is applied to an object when something such as a lever is used.","ex":{"en":"The spade and fork have longer shafts, providing better leverage.","cn":"锹和耙的手柄较长，可发挥较好的杠杆作用。"}},{"pos":"VERB 动词","cn":"举债经营；为…融资","en":"To leverage a company or investment means to use borrowed money in order to buy it or pay for it.","ex":{"en":"He might feel that leveraging the company at a time when he sees tremendous growth opportunities would be a mistake.","cn":"他也许觉得，在他认为大有可为的时候让公司借贷经营是一个错误。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"influence that you can use to make people do what you want","cn":"影响"},{"en":"the action, power, or use of a lever","cn":"杠杆作用﹔杠杆力量﹔杠杆的使用"},{"en":"to make money available to someone in order to invest or to buy something such as a company","cn":"为…融资﹐使借贷经营"}]},"vocab":{"pos":"n v","senses":[{"en":"If you have leverage , you hold the advantage in a situation or the stronger position in a contest, physical or otherwise."}]},"collocations":{"phrases":["ADJ. enough, sufficient | extra | maximum","VERB + LEVERAGE have He tried to push the door open, but he didn't have sufficient leverage. | gain, get, obtain | apply, exert Position the","ADJ. economic, political","VERB + LEVERAGE have | gain They are determined to gain more political leverage. | give sb"]},"media":{"uk":"media/ldoce/hwd/bre/2/leverage_n0205.mp3","us":"media/ldoce/hwd/ame/2/leverage.mp3"},"examples":[{"en":"The company needs to leverage its resources.","cn":"该公司需要充分利用其资源。"},{"en":"diplomatic leverage","cn":"外交影响力"}],"oxford":{"phon":"ˈliːvərɪdʒ","pos":"noun","senses":[{"en":"the ability to influence what people do","cn":"影响力","lab":"formal","ex":{"en":"diplomatic leverage","cn":"外交影响力"}},{"en":"the act of using a lever to open or lift something; the force used to do this","cn":"杠杆作用；杠杆效力","lab":"specialist","ex":{"en":"A longer piece of wood would give you greater leverage.","cn":"更长的木头会给你更大的杠杆作用。"}},{"en":"the relationship between the amount of money that a company owes and the value of its shares","cn":"杠杆比率；资本与负债比率","lab":"British English also"},{"en":"the practice of borrowing money for an investment, in the hope of increasing profits in the future","cn":"为了增加未来利润而借钱进行投资的做法","lab":"business","ex":{"en":"While leverage presents opportunities for increasing the total return on investments, it also has the potential to increase losses.","cn":"虽然杠杆提供了增加总投资回报的机会，但它也有可能增加损失。"}},{"en":"to get as much advantage or profit as possible from something that you have","cn":"充分利用","ex":{"en":"The company needs to leverage its resources.","cn":"该公司需要充分利用其资源。"},"pos":"verb"}]}},"leipzig":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a city in eastern central Germany, which has a famous university and is an important centre for business","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/p028-000007304.mp3","us":"media/ldoce/hwd/ame/e/p028-000007304.mp3"}},"leprosy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"麻风（病）","en":"Leprosy is an infectious disease that damages people's flesh."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very serious infectious disease in which the flesh and nerves are gradually destroyed","cn":"麻风"}]},"vocab":{"pos":"n","senses":[{"en":"Leprosy is a horrible and chronic contagious disease that involves the rotting of flesh."}]},"collocations":{"phrases":["VERB + LEPROSY have, suffer from | contract","LEPROSY + NOUN bacillus | patient, sufferer, victim •"]},"media":{"uk":"media/ldoce/hwd/bre/4/leprosy0205.mp3","us":"media/ldoce/hwd/ame/2/leprosy.mp3"},"oxford":{"phon":"ˈleprəsi","pos":"noun","senses":[{"en":"a disease that causes painful white areas on the skin and can destroy nerves, muscles, etc.","cn":"麻风"}]}},"leaflet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"传单；小册子","en":"A leaflet is a little book or a piece of paper containing information about a particular subject.","ex":{"en":"Campaigners handed out leaflets on passive smoking.","cn":"活动人士派发了有关被动吸烟的宣传页。"}},{"pos":"VERB 动词","cn":"在（某处）散发传单（或小册子）","en":"If you leaflet a place, you distribute leaflets there, for example by handing them to people, or by putting them through letter boxes.","ex":{"en":"We've leafleted the university today to try to drum up some support","cn":"我们今天在大学散发了传单，希望能争取到支持。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very short book with paper covers that usually contains information on one particular subject","cn":""},{"en":"a thin book with paper covers that gives information on something you may want to buy or advertises something","cn":""},{"en":"a small book or piece of paper, often only one or two folded pages, that advertises something or gives information on a particular subject","cn":""}]},"collocations":{"phrases":["ADJ. free a free leaflet explaining your tax return | helpful, useful | explanatory, information, instruction | promotional, publicity | cam","QUANT. copy","VERB + LEAFLET issue, produce, publish The Health Council issued hundreds of leaflets. | deliver, distribute, give out, hand out, send out C","LEAFLET + VERB advertise sth, explain sth","PREP. in a/the ~ More details are given in our promotional leaflet."]},"media":{"uk":"media/ldoce/hwd/bre/b/leaflet_n0205.mp3","us":"media/ldoce/hwd/ame/d/leaflet.mp3"},"examples":[{"en":"We did a lot of leafleting in the area.","cn":"我们在此地散发了许多传单。"},{"en":"a leaflet on local places of interest","cn":"介绍当地名胜的小册子"}],"oxford":{"phon":"ˈliːflət","pos":"noun","senses":[{"en":"a printed sheet of paper or a few printed pages that are given free to advertise or give information about something","cn":"散页印刷品；传单；（宣传或广告）小册子","ex":{"en":"We picked up a few leaflets on local places of interest.","cn":"我们拿了几本宣传当地名胜的小册子。"}},{"en":"to give out leaflets to people","cn":"散发传单（或小册子）","ex":{"en":"We did a lot of leafleting in the area.","cn":"我们在此地散发了许多传单。"},"pos":"verb"}]}},"lethal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"致命的；可致死的","en":"A substance that is lethal can kill people or animals.","ex":{"en":"...a lethal dose of sleeping pills.","cn":"剂量足以致命的安眠药"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"危害极大的；毁灭性的","en":"If you describe something as lethal, you mean that it is capable of causing a lot of damage.","ex":{"en":"High-powered cars are lethal weapons in the hands of inexperienced drivers","cn":"马力大的汽车到了缺乏经验的司机手中便成了毁灭性的武器。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a fatal accident, illness, or injury is one that causes death","cn":""},{"en":"something that is lethal can cause death - use this especially about weapons or substances","cn":""},{"en":"something such as a disease or poison that is deadly can cause death","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Lethal refers to anything dangerous enough to cause death. The cobra's venom is so lethal that if you get bitten and can't find the antidote, it's lights out forever."}]},"collocations":{"phrases":["VERBS be, prove","ADV. absolutely All these knives are absolutely lethal. | pretty | potentially It was a potentially lethal mixture of drugs.","PREP. to The pesticide is lethal to all insect life."]},"media":{"uk":"media/ldoce/hwd/bre/5/lethal0205.mp3","us":"media/ldoce/hwd/ame/8/lethal.mp3"},"examples":[{"en":"( figurative ) The closure of the factory dealt a lethal blow to the town.","cn":"那家工厂的关闭对这座城镇是致命的打击。"},{"en":"You and that car — it's a lethal combination!","cn":"你和那辆车真是致命的组合！"}],"oxford":{"phon":"ˈliːθl","pos":"adjective","senses":[{"en":"causing or able to cause death","cn":"致命的；可致死的","lab":"figurative","ex":{"en":"She had been given a lethal dose of poison.","cn":"已给她服下致死剂量的毒药。"}},{"en":"causing or able to cause a lot of harm or damage","cn":"危害极大的；破坏性极大的","lab":"informal","ex":{"en":"You and that car—it's a lethal combination!","cn":"你和那辆车真是致命的组合！"}}]}},"legality":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"合法（性）","en":"If you talk about the legality of an action or situation, you are talking about whether it is legal or not.","ex":{"en":"The auditor has questioned the legality of the contracts.","cn":"审计员质疑这些合同是否合法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is legal is allowed by law","cn":""},{"en":"actions or methods that are lawful are allowed by law, especially as compared with actions or methods that are not legal","cn":""},{"en":"legitimate activities, organizations, or claims are done or work according to, normal laws and rules","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you’re wondering about the legality of not paying taxes on your lottery winnings, then you’re wondering if it’s legal not to pay the taxes."}]},"collocations":{"phrases":["ADJ. doubtful, dubious","VERB + LEGALITY challenge, question Her lawyer is challenging the legality of the court order. | assert, recognize, uphold The government do","PHRASES doubt/doubts about the legality of sth"]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41legality.mp3","us":"media/ldoce/hwd/ame/e/legality.mp3"},"examples":[{"en":"You need a lawyer to explain all the legalities of the contracts.","cn":"你需要律师来解释这些合同在法律上的各项细节。"},{"en":"They intended to challenge the legality of his claim in the courts.","cn":"他们打算在法庭上对他索赔的合法性提出质疑。"}],"oxford":{"phon":"lɪˈɡæləti","pos":"noun","senses":[{"en":"the fact of being legal","cn":"合法（性）","g":"[uncountable]","ex":{"en":"They intended to challenge the legality of his claim in the courts.","cn":"他们打算在法庭上对他索赔的合法性提出质疑。"}},{"en":"the legal aspect of an action or a situation","cn":"（某行为或情况的）法律方面","g":"[countable, usually plural]","ex":{"en":"You need a lawyer to explain all the legalities of the contracts.","cn":"你需要律师来解释这些合同在法律上的各项细节。"}}]}},"lessen":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）缩小；（使）减少；（使）减轻","en":"If something lessens or you lessen it, it becomes smaller in size, amount, degree, or importance.","ex":{"en":"He is used to a lot of attention from his wife, which will inevitably lessen when the baby is born","cn":"他习惯了妻子对他的百般关注，但孩子出生后这种关注就会不可避免地减少。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something such as fear, anxiety, trouble or laughter subsides , it gradually decreases","cn":""},{"en":"if something such as people's liking or support for something or someone wanes , that feeling gradually becomes slightly less and will probably continue to decrease","cn":""},{"en":"if a possibility or chance recedes , it gradually becomes less and less likely","cn":""}]},"collocations":{"phrases":["ADV. considerably, greatly, significantly Eating a good diet significantly lessens the risk of heart disease. | gradually Time had gradually","VERB + LESSEN begin to The noise began to lessen. | try to | tend to Too much background detail tends to lessen the impact of the central im"]},"media":{"uk":"media/ldoce/hwd/bre/9/lessen0205.mp3","us":"media/ldoce/hwd/ame/b/lessen.mp3"},"examples":[{"en":"to lessen the risk/impact/effect of sth","cn":"减少某事物的风险/影响/效果"},{"en":"The noise began to lessen.","cn":"噪音开始减弱。"}],"oxford":{"phon":"ˈlesn","pos":"verb","senses":[{"en":"to become or make something become smaller, weaker, less important, etc.","cn":"（使）变小，变少，减弱，减轻","ex":{"en":"The noise began to lessen.","cn":"噪音开始减弱。"}}]}},"legislature":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"立法机关；议会","en":"The legislature of a particular state or country is the group of people in it who have the power to make and pass laws.","ex":{"en":"The proposals before the legislature include the creation of two special courts to deal exclusively with violent crimes.","cn":"呈交立法机关的提案内容包括成立两个专门审理暴力犯罪的特别法庭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an institution that has the power to make or change laws","cn":"立法机关"},{"en":"state/national/federal etc legislature the state legislature of Virginia","cn":"弗吉尼亚州立法机构"}]},"vocab":{"pos":"n","senses":[{"en":"A legislature is a governing body that makes laws and can also amend or repeal them."}]},"collocations":{"phrases":["ADJ. highest, supreme | bicameral, unicameral | 109-member, etc. | elected | standing | central, federal, national, provincial, state","VERB + LEGISLATURE be elected to She is the youngest woman to be elected to the national legislature.","LEGISLATURE + VERB comprise sth, consist of sth The legislature comprises a 212-member Chamber of Deputies elected for a four-year term. | p"]},"media":{"uk":"media/ldoce/hwd/bre/5/legislature0205.mp3","us":"media/ldoce/hwd/ame/3/legislature.mp3"},"examples":[{"en":"a democratically elected legislature","cn":"民主选举产生的立法机关"},{"en":"the national/state legislature","cn":"国家/州立法机构"}],"oxford":{"phon":"ˈledʒɪslətʃə(r)","pos":"noun","senses":[{"en":"a group of people who have the power to make and change laws","cn":"立法机关","ex":{"en":"a democratically elected legislature","cn":"民主选举产生的立法机关"}}]}},"leeds":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a city in West Yorkshire, in the north of England, which is an important industrial and business centre. It is also a popular place with young people because of its many nightclub s .","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/p028-000007283.mp3","us":"media/ldoce/hwd/ame/1/p028-000007283.mp3"},"oxford":{"phon":"liːdz","pos":"","senses":[{"en":"a city in West Yorkshire, England. In the 16th century it began to be an important centre for the production of woollen cloth, and later became a centre of the Industrial Revolution. The Leeds and Liverpool Canal was opened in 1816. It remains an important industrial city. Its famous buildings include the Town Hall (1853-8), the City Art Gallery (1888) and Armley Mills, a museum of local industrial history. The Royal Armouries Museum opened there in 1996 and Thackray's Medical Museum in 1997. There are two universities in the city. The Leeds International Pianoforte Competition, open to professional piano players under 30, was started in 1963 and held in the city every three years.","cn":"利兹（英格兰西约克郡城市。16 世纪开始成为重要的毛呢生产中心，随后成为工业革命的中心。利兹和利物浦运河于 1816 年开通。利兹如今仍是重要的工业城市。当地著名建筑包括建于 1853-58 年的市政厅、建于 1888 年的市美术馆、由阿姆利纺织厂改建的当地工业历史博物馆。市内有两所大学。三年一届的利兹国际钢琴比赛创办于 1963 年，参赛者为 30 岁以下的专业钢琴演奏者）"}]}},"legacy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"遗产；遗赠","en":"A legacy is money or property which someone leaves to you when they die.","ex":{"en":"You could make a real difference to someone's life by leaving them a generous legacy.","cn":"慷慨留下您的遗产，改写他人的人生。"}},{"pos":"N-COUNT 可数名词","cn":"（事件或历史的）遗留问题，后遗症","en":"A legacy of an event or period of history is something which is a direct result of it and which continues to exist after it is over.","ex":{"en":"...a programme to overcome the legacy of inequality and injustice created by Apartheid","cn":"旨在消除种族隔离政策所遗留的不平等与不公正问题的项目"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens or exists as a result of things that happened at an earlier time","cn":"遗留的问题﹐后遗症"},{"en":"money or property that you receive from someone after they die","cn":"遗产﹐遗赠"},{"en":"a legacy system, piece of software etc is one that people continue to use, although more modern ones are available 〔","cn":"系统﹑软件等〕旧版本的﹐老旧的"}]},"vocab":{"pos":"n","senses":[{"en":"Use the word, legacy, for something handed down from one generation to the next. A retiring company president might leave a legacy of honesty and integrity."}]},"collocations":{"phrases":["ADJ. generous, large | small","VERB + LEGACY bequeath (sb), leave (sb) | get, receive He received a large legacy from his uncle.","PREP. in a/the ~ She left her the money in a legacy. | ~ from a legacy from my old teacher","PHRASES heir to a legacy She is the heir to a legacy of &pound; 1 million. 2 result of previous events","ADJ. enduring | historical These problems have arisen as a result of historical legacies. | bitter, grim","VERB + LEGACY bequeath (sb), leave (sb), leave behind the enduring legacy bequeathed by the war years","PREP. ~ from Such attitudes are a legacy from colonial times."]},"media":{"uk":"media/ldoce/hwd/bre/1/legacy0205.mp3","us":"media/ldoce/hwd/ame/8/legacy.mp3"},"examples":[{"en":"How can we integrate new technology with our legacy systems?","cn":"我们该如何将新技术整合到我们老化的系统上？"},{"en":"They each received a legacy of $5 000.","cn":"他们每人得到了 5 000 元的遗产。"}],"oxford":{"phon":"ˈleɡəsi","pos":"noun","senses":[{"en":"money or property that is given to you by somebody when they die","cn":"遗产；遗赠财物","ex":{"en":"They each received a legacy of $5 000.","cn":"他们每人得到了 5 000 美元的遗产。"}},{"en":"a situation that exists now because of events, actions, etc. that took place in the past","cn":"遗留影响；后遗症","ex":{"en":"Future generations will be left with a legacy of pollution and destruction.","cn":"留给子孙后代的将是环境的污染与破坏。"}},{"en":"something that somebody has done successfully and that has positive effects even after they retire or die","cn":"遗产：某人成功完成的事情，即使退休或死亡也有积极影响","ex":{"en":"She was an active anti-bullying campaigner, and after she died her family set up a charity to ensure that her legacy lives on.","cn":"她是一位积极的反欺凌活动家，在她去世后，她的家人成立了一家慈善机构，以确保她的遗产得以延续。"}},{"en":"the idea that something created for an event in the past can be used in a different way in the future","cn":"遗留：过去为事件创建的东西可以在将来以不同方式使用的想法","ex":{"en":"In the UK, the Olympic legacy lives on most strongly in East London where the Olympic Park is located.","cn":"在英国，奥林匹克遗产在奥林匹克公园所在的东伦敦最为强烈。"}},{"en":"used to describe a computer system or product that is no longer available to buy but is still used because it would be too difficult or expensive to replace it","cn":"（计算机系统或产品）已停产的，老化的，老式的","ex":{"en":"How can we integrate new technology with our legacy systems?","cn":"我们该如何将新技术整合到我们老化的系统上？"},"pos":"adjective"},{"en":"created to be remembered and to have an effect that continues into the future","cn":"遗留物：被创造并被记住并具有持续到未来的影响","ex":{"en":"The new arts centre is a legacy project that will boost tourism and create jobs.","cn":"新的艺术中心是一个遗产项目，将促进旅游业和创造就业机会。"},"pos":"adjective"}]}},"lease":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"租约；租契；出租协议","en":"A lease is a legal agreement by which the owner of a building, a piece of land, or something such as a car allows someone else to use it for a period of time in return for money.","ex":{"en":"He took up a 10 year lease on the house at Rossie Priory.","cn":"他签了一份10年租约，租下了罗茜大宅的房子。"}},{"pos":"VERB 动词","cn":"租借；租用；出租","en":"If you lease property or something such as a car from someone or if they lease it to you, they allow you to use it in return for regular payments of money.","ex":{"en":"He went to Toronto, where he leased an apartment","cn":"他去了多伦多，在那儿租了一间公寓。"}},{"pos":"PHRASE 短语","cn":"（较昔日更加）焕发生机；重振雄风","en":"If you say that someone or something has been given a new lease of life, you are emphasizing that they are much more lively or successful than they have been in the past.","ex":{"en":"The operation has given me a new lease of life.","cn":"手术使我重获新生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a legal agreement which allows you to use a building, car etc for a period of time, in return for rent 〔","cn":"房子﹑汽车等的〕租约﹐租契"},{"en":"if something has a new lease of life, it is changed or repaired so that it can continue 〔","cn":"某物经改装或修理后的〕延续使用寿命"},{"en":"if someone has a new lease of life, they become healthy, active, or happy again after being weak, ill, or tired 〔","cn":"某人〕重获的健康[幸福]"}]},"vocab":{"pos":"n v","senses":[{"en":"To lease something is to borrow it in exchange for money. If you lease a car from a dealer, for example, you make payments and you get to drive the car, but at the end of the contract you have to give it back."}]},"collocations":{"phrases":["ADJ. long, long-term | short, short-term | ten-year, etc. | business, commercial | building, mining","VERB + LEASE have, hold They've got a lease with five years to run. | draw up | acquire, buy, enter into, get, negotiate, obtain, sign, take","LEASE + VERB run The lease runs from April 19. | take effect | come up for renewal, expire, run out","PREP. in a/the ~ a new clause in the lease | on a ~ The company holds the building on a long lease. | under a/the ~ Under the new lease, the","PHRASES a clause in a lease, a condition of a lease, the length/period/term of a lease, a provision in a lease, the terms of the lease"]},"media":{"uk":"media/ldoce/hwd/bre/a/lease_n0205.mp3","us":"media/ldoce/hwd/ame/e/lease1.mp3"},"examples":[{"en":"They lease the land from a local farmer.","cn":"他们从当地一位农场主手中租得这块土地。"},{"en":"A local farmer leased them the land.","cn":"这块地是当地的一个农场主租给他们的。"}],"oxford":{"phon":"liːs","pos":"noun","senses":[{"en":"a legal agreement that allows you to use a building, a piece of equipment or some land for a period of time, usually in return for rent","cn":"（房屋、设备或土地的）租约，租契","lab":"especially North American English","ex":{"en":"to take out a lease on a house","cn":"办理房屋租约"}},{"en":"to use or let somebody use something, especially property or equipment, in exchange for rent or a regular payment","cn":"租用，租借，出租（尤指房地产或设备）","ex":{"en":"We lease all our computer equipment.","cn":"我们所有的计算机设备都是租来的。"},"pos":"verb"}]}},"lender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"放款人；贷款机构","en":"A lender is a person or an institution that lends money to people.","ex":{"en":"...the six leading mortgage lenders.","cn":"6大按揭贷款机构"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or organization that lends money","cn":""},{"en":"a person or business that is owed money by another person or business","cn":""},{"en":"a person or small business that lends money, at extremely high interest rates - use this when you disapprove of people who make money in this way","cn":""}]},"collocations":{"phrases":["ADJ. big, large, leading, major The bank is the largest mortgage lender in the country. | money, mortgage","PREP. ~ to The bank was an important lender to the British government."]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41lender.mp3","us":"media/ldoce/hwd/ame/7/ld41lender.mp3"},"examples":[{"en":"Several lenders are offering very attractive rates of interest at the moment.","cn":"目前有几家贷款机构贷款利率非常优惠。"}],"oxford":{"phon":"ˈlendə(r)","pos":"noun","senses":[{"en":"a person or an organization that lends money","cn":"放款人","ex":{"en":"The bank is the largest mortgage lender in the country.","cn":"银行是全国最大的按揭贷款方。"}}]}},"leniency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仁慈；宽大","en":"Leniency is a lenient attitude or lenient behaviour.","ex":{"en":"The judge rejected pleas for leniency and sentenced him to six months in prison","cn":"法官驳回了宽大处理的请求，判处他6个月的监禁。"}}]},"vocab":{"pos":"n","senses":[{"en":"Leniency is a noun that refers to the lessening of a punishment or chore. Your father's leniency , for example, resulted in you not having to paint the entire house like your mother wanted. Instead you just had to paint the garage."}]},"collocations":{"phrases":["ADJ. great Judges are advised to show greater leniency towards first-time offenders. | excessive, undue","VERB + LENIENCY show | appeal for, beg for","PREP. ~ for She begged for leniency for her son. | ~ of the undue leniency of the sentence | ~ to Police offer leniency to criminals in retu","PHRASES a plea for leniency Even the victim's family made a plea for leniency on behalf of the accused."]},"examples":[{"en":"She appealed to the judge for leniency.","cn":"她向法官请求宽大处理。"}],"oxford":{"phon":"ˈliːniənsi","pos":"noun","senses":[{"en":"the fact of being less strict than expected when punishing somebody or when making sure that rules are obeyed","cn":"（惩罚或执法时）宽大的，宽容的，仁慈的","ex":{"en":"She appealed to the judge for leniency.","cn":"她恳求法官宽大处理。"}}]}},"lexicon":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（某一学科、个人或群体的）全部词汇","en":"The lexicon of a particular subject is all the terms associated with it. The lexicon of a person or group is all the words they commonly use.","ex":{"en":"...the lexicon of management","cn":"管理学词汇"}},{"pos":"N-COUNT 可数名词","cn":"（某一语言或学科的）词汇表","en":"A lexicon is an alphabetical list of the words in a language or the words associated with a particular subject."},{"pos":"N-COUNT 可数名词","cn":"（尤指希腊语、希伯来语等古老语言的）词典，字典","en":"A lexicon is a dictionary, especially of a very old language such as Greek or Hebrew."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"all the words and phrases used in a language or that a particular person knows 〔","cn":"某种语言或某人知晓的〕全部词汇"},{"en":"an alphabetical list of words with their meanings, especially on a particular subject or in a particular language 〔","cn":"尤指某学科或语言的〕词汇表"}]},"vocab":{"pos":"n","senses":[{"en":"A lexicon is the vocabulary of a language or subject. \"No-hitter,\" \"go-ahead run,\" and \"Baltimore chop\" are part of the baseball lexicon ."}]},"media":{"uk":"media/ldoce/hwd/bre/a/lexicon0205.mp3","us":"media/ldoce/hwd/ame/2/lexicon.mp3"},"examples":[{"en":"a lexicon of technical scientific terms","cn":"科技术语词汇表"},{"en":"the lexicon of finance and economics","cn":"财经词汇"}],"oxford":{"phon":"ˈleksɪkən","pos":"noun","senses":[{"en":"all the words and phrases used in a particular language or subject; all the words and phrases used and known by a particular person or group of people","cn":"（某语言或学科、某人或群体使用的）全部词汇","g":"[singular]","lab":"linguistics","ex":{"en":"the lexicon of finance and economics","cn":"财经词汇"}},{"en":"a list of words on a particular subject or in a language in alphabetical order","cn":"（某学科或语言的）词汇表","g":"[countable]","ex":{"en":"a lexicon of technical scientific terms","cn":"科技术语词汇表"}},{"en":"a dictionary, especially one of an ancient language, such as Greek or Hebrew","cn":"（尤指希腊语或希伯来语等古代语言的）词典，字典","g":"[countable]"}]}}});
